## 1. Paste the Final formulas

In `Final!A1:F1`, enter these headers: **Timestamp, Name, Email, JoinedBefore, Phone, PreferredPark**.

Paste this into `Final!A2` for **email-bearing rows only**:

```gs
=IFNA(FILTER(
  {Raw!I2:I421,Raw!L2:L421,Raw!K2:K421,Raw!G2:G421,Raw!H2:H421,Raw!J2:J421},
  Raw!P2:P421="OK",
  Raw!O2:O421<>"SUPERSEDED",
  Raw!K2:K421<>""
),"")
```

### Include unique submissions with no email

Use this **instead of** the first formula to get both sets of rows in one table:

```gs
=IFNA(FILTER(
  {Raw!I2:I421,Raw!L2:L421,Raw!K2:K421,Raw!G2:G421,Raw!H2:H421,Raw!J2:J421},
  Raw!P2:P421="OK",
  Raw!O2:O421<>"SUPERSEDED",
  ((Raw!K2:K421<>"")+((Raw!K2:K421="")*(Raw!L2:L421<>"")*(Raw!N2:N421="")))>0
),"")
```

This keeps a blank-email row only if it has a name and `N` found no same-name submission within 10 minutes, including matches against rows that *do* have an email. Format `Final!A:A` as **Date time**. Column B will be lowercase because `L` is your normalized name key. If your helpers are on `Clean`, replace `Raw!` with `Clean!`; extend row `421` in the filters **and** helper formulas as responses grow.

### Two helper fixes so the filters work as intended

The original `P` marks **both** rows in a repeated-email group `REVIEW`, so neither can reach `Final`. The original `O` also leaves equal timestamps tied. If your policy is “latest submission per email wins,” use these replacements and fill down:

**`Raw!O2` — latest valid timestamp wins; on a tie, the later sheet row wins:**

```gs
=IF(OR(K2="",NOT(ISNUMBER(I2))),"",
  IF(OR(
    COUNTIFS($K$2:$K$421,K2,$I$2:$I$421,">"&I2)>0,
    COUNTIFS($K$2:K2,K2,$I$2:I2,I2)<COUNTIFS($K$2:$K$421,K2,$I$2:$I$421,I2)
  ),"SUPERSEDED",""))
```

**`Raw!P2` — repeated email is informational; ambiguous blank-email rows still need review:**

```gs
=IF(COUNTA(A2:F2)=0,"",
  IF(OR(G2="REVIEW",H2="REVIEW",NOT(ISNUMBER(I2)),J2="REVIEW",
        AND(K2="",OR(L2="",N2<>""))),
     "REVIEW","OK"))
```

Keep any intentional manual holds when updating `P`. If the latest timestamped submission has a bad phone or an unmapped park, it stays out of `Final`; the filter does **not** silently fall back to an older submission. In your Maya example, row 2 wins the timestamp tie, but it still needs a valid phone before it can appear.

## 2. Apps Script for an automatically rebuilt snapshot

The formulas are simpler for a live view. Use this script if you want `Final` written as values after each form submission. It reads `Raw!A:F` and `ParkMap!A:B`, leaves your helpers alone, and writes a separate `Review` tab with source row numbers and reasons. It **overwrites `Final` and `Review`**, so remove the `Final` spill formula if you switch to the script.

```javascript
function rebuildFinal() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const raw = ss.getSheetByName('Raw'), map = ss.getSheetByName('ParkMap');
  const tz = ss.getSpreadsheetTimeZone(), day = 86400000, minutes = 10;
  const text = v => String(v ?? '').trim();
  const key = v => text(v).toLowerCase().replace(/[^a-z]/g, '');
  const body = (s, cols) => s.getLastRow() < 2 ? [] :
    s.getRange(2, 1, s.getLastRow() - 1, cols).getValues();
  const parks = new Map(body(map, 2).map(([k, v]) => [key(k), text(v)]));

  function timestamp(v) {
    if (v instanceof Date) {
      return Date.parse(Utilities.formatDate(v, tz, "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"));
    }
    // Text dates: US M/D/YY(YY) or D-Mon-YYYY, optionally with 24-hour time.
    const s = text(v);
    const a = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4}|\d{2})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?$/);
    const b = s.match(/^(\d{1,2})-([a-z]{3})-(\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?$/i);
    const m = a || b;
    if (!m) return NaN;
    const month = a ? +a[1] - 1 :
      'jan feb mar apr may jun jul aug sep oct nov dec'.split(' ').indexOf(b[2].toLowerCase());
    const d = +(a ? a[2] : b[1]);
    let y = +m[3];
    if (m[3].length === 2) y += y < 30 ? 2000 : 1900;
    const [h, min, sec] = m.slice(4).map(x => +(x || 0));
    const t = Date.UTC(y, month, d, h, min, sec), check = new Date(t);
    return month >= 0 && month < 12 && h < 24 && min < 60 && sec < 60 &&
      check.getUTCMonth() === month && check.getUTCDate() === d ? t : NaN;
  }

  const rows = body(raw, 6).flatMap(([ts, nm, em, yn, ph, pk], i) => {
    if (![ts, nm, em, yn, ph, pk].some(v => text(v) !== '')) return [];
    const name = text(nm).toLowerCase().replace(/\s+/g, ' ');
    const email = text(em).toLowerCase(), t = timestamp(ts);
    const joined = /^y(es)?$/i.test(text(yn)) ? 'Yes' :
      /^no?$/i.test(text(yn)) ? 'No' : '';
    const phone = text(ph).replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
    const park = parks.get(key(pk)) || '';
    return [{row: i + 2, t, name, email, joined, phone, park}];
  });

  const latest = new Map(), final = [], review = [];
  for (const r of rows) {
    if (r.email && Number.isFinite(r.t) &&
        (!latest.has(r.email) || r.t >= latest.get(r.email).t)) latest.set(r.email, r);
  }
  for (const r of rows) {
    const issues = [];
    if (!Number.isFinite(r.t)) issues.push('Timestamp');
    if (!r.joined) issues.push('JoinedBefore');
    if (r.phone.length !== 10) issues.push('Phone');
    if (!r.park) issues.push('PreferredPark');
    if (!r.email && (!r.name || rows.some(s =>
      s !== r && s.name === r.name && Math.abs(s.t - r.t) <= minutes * 60000
    ))) issues.push('Blank email: missing name or nearby name match');

    if (issues.length) review.push([r.row, 'REVIEW', issues.join('; ')]);
    else if (!r.email || latest.get(r.email) === r) {
      final.push([r.t / day + 25569, r.name, r.email, r.joined, r.phone, r.park]);
    }
  }

  function write(name, header, data) {
    const s = ss.getSheetByName(name) || ss.insertSheet(name);
    s.clearContents();
    if (name === 'Final' && data.length) {
      s.getRange(2, 1, data.length, 1).setNumberFormat('yyyy-mm-dd hh:mm:ss');
      s.getRange(2, 5, data.length, 1).setNumberFormat('@');
    }
    s.getRange(1, 1, data.length + 1, header.length).setValues([header, ...data]);
  }
  write('Final', ['Timestamp', 'Name', 'Email', 'JoinedBefore', 'Phone', 'PreferredPark'], final);
  write('Review', ['Raw row', 'Status', 'Reasons'], review);
}
```

Paste it into **Extensions → Apps Script** and run `rebuildFinal` once to authorize and verify the output. Then add an installable trigger for `rebuildFinal`: **From spreadsheet → On form submit**. If new rows arrive by import rather than through a linked Google Form, use a time-driven trigger instead. The script assumes month-first slash dates; if your text dates are day-first, adjust the parser before enabling the trigger.

Paste this into **Extensions → Apps Script**, save it, then select the **Raw** tab and run `cleanVolunteerSurvey`. The script adds or refreshes the ten helper columns by header name. It does not change the six source columns or delete any rows.

**Assumptions:** Headers are in row 1 on both tabs. Text dates use month/day/year by default (`3/4/21` → March 4, 2021); change `DATE_ORDER` to `'DMY'` if your source uses day/month/year. Date-only values are treated as midnight in the spreadsheet’s time zone. Phone numbers must have 10 digits after removing punctuation and an optional leading `1`; the script won’t guess missing area codes.

```javascript
function cleanVolunteerSurvey() {
  const DATE_ORDER = 'MDY'; // Change to 'DMY' for day/month/year text dates.
  const WINDOW_MS = 10 * 60 * 1000;

  const sourceHeaders = [
    'Timestamp', 'Name', 'Email', 'JoinedBefore', 'Phone', 'PreferredPark'
  ];
  const helperHeaders = [
    'NormalizedJoined', 'CleanPhone', 'ParsedTimestamp', 'CleanPark',
    'EmailKey', 'NameKey', 'DupEmailFlag', 'DupNameTimeFlag',
    'Superseded', 'ReviewFlag'
  ];

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const raw = ss.getActiveSheet();
  if (raw.getName() !== 'Raw') {
    throw new Error('Select the Raw tab before running this script.');
  }
  if (!['MDY', 'DMY'].includes(DATE_ORDER)) {
    throw new Error('DATE_ORDER must be MDY or DMY.');
  }

  const parkSheet = ss.getSheetByName('ParkMap');
  if (!parkSheet) throw new Error('Missing sheet: ParkMap.');

  const tz = ss.getSpreadsheetTimeZone();
  const text = value => String(value ?? '').trim();
  const parkKey = value => text(value).toLowerCase().replace(/[^a-z]/g, '');
  const parkMap = new Map();

  const mapRowCount = parkSheet.getLastRow() - 1;
  if (mapRowCount > 0) {
    parkSheet.getRange(2, 1, mapRowCount, 2).getDisplayValues()
      .forEach(([alias, canonical], i) => {
        const key = parkKey(alias);
        const name = text(canonical);
        if (!text(alias) && !name) return;
        if (!key || !name) {
          throw new Error(`ParkMap row ${i + 2} needs a valid key and canonical name.`);
        }
        if (parkMap.has(key) && parkMap.get(key) !== name) {
          throw new Error(`Conflicting ParkMap entries for "${key}".`);
        }
        parkMap.set(key, name);
      });
  }

  const values = raw.getDataRange().getValues();
  const headers = values[0].map(text);
  const columns = new Map();

  for (const header of [...sourceHeaders, ...helperHeaders]) {
    const index = headers.indexOf(header);
    if (index !== -1 && index !== headers.lastIndexOf(header)) {
      throw new Error(`Duplicate header in Raw: ${header}`);
    }
    if (index !== -1) columns.set(header, index);
  }
  for (const header of sourceHeaders) {
    if (!columns.has(header)) throw new Error(`Missing Raw header: ${header}`);
  }

  function normalizeJoined(value) {
    const s = text(value).toLowerCase();
    if (/^y(es)?$/.test(s)) return 'Yes';
    if (/^no?$/.test(s)) return 'No';
    return 'REVIEW';
  }

  function cleanPhone(value) {
    let digits = text(value).replace(/\D/g, '');
    if (digits.length === 11 && digits.startsWith('1')) {
      digits = digits.slice(1);
    }
    return digits.length === 10 ? digits : 'REVIEW';
  }

  function parseTimestamp(value) {
    if (value instanceof Date) {
      return Number.isFinite(value.getTime()) ? value : null;
    }

    const s = text(value);
    let year, month, day, hour, minute, second, meridiem;

    // Examples: 4/3/2021 09:12, 3/4/21, 4/3/2021 9:12 AM.
    const numeric = s.match(
      /^(\d{1,2})\/(\d{1,2})\/(\d{4}|\d{2})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?(?:\s*(AM|PM))?)?$/i
    );

    if (numeric) {
      const [, first, secondPart, y, h, m, sec, ampm] = numeric;
      [month, day] = DATE_ORDER === 'MDY'
        ? [first, secondPart] : [secondPart, first];
      year = y.length === 2 ? 2000 + Number(y) : Number(y);
      [hour, minute, second, meridiem] = [h, m, sec, ampm];
    } else {
      // Example: 03-Mar-2021, optionally followed by a time.
      const named = s.match(
        /^(\d{1,2})-([a-z]{3})-(\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?(?:\s*(AM|PM))?)?$/i
      );
      if (!named) return null;

      const [, d, mon, y, h, m, sec, ampm] = named;
      month = ('jan feb mar apr may jun jul aug sep oct nov dec')
        .split(' ').indexOf(mon.toLowerCase()) + 1;
      if (!month) return null;
      [day, year, hour, minute, second, meridiem] = [d, y, h, m, sec, ampm];
    }

    hour = Number(hour || 0);
    if (meridiem) {
      if (hour < 1 || hour > 12) return null;
      hour = hour % 12 + (meridiem.toUpperCase() === 'PM' ? 12 : 0);
    }

    const pad = n => String(Number(n)).padStart(2, '0');
    const stamp = `${year}-${pad(month)}-${pad(day)} ` +
                  `${pad(hour)}:${pad(minute || 0)}:${pad(second || 0)}`;
    const format = 'yyyy-MM-dd HH:mm:ss';

    try {
      const date = Utilities.parseDate(stamp, tz, format);
      // Reject invalid dates/times that the parser silently rolls forward.
      return Utilities.formatDate(date, tz, format) === stamp ? date : null;
    } catch (e) {
      return null;
    }
  }

  const byEmail = new Map();
  const byName = new Map();

  function addToGroup(groups, key, row) {
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(row);
  }

  const rows = values.slice(1).map((row, i) => {
    const fields = sourceHeaders.map(header => row[columns.get(header)]);
    if (fields.every(value => text(value) === '')) return null;

    const [timestamp, name, email, joined, phone, park] = fields;
    const date = parseTimestamp(timestamp);
    const r = {
      index: i,
      joined: normalizeJoined(joined),
      phone: cleanPhone(phone),
      date,
      ms: date ? date.getTime() : null,
      park: parkMap.get(parkKey(park)) || 'REVIEW',
      emailKey: text(email).toLowerCase(),
      nameKey: text(name).toLowerCase().replace(/\s+/g, ' '),
      dupEmail: '',
      dupName: '',
      superseded: ''
    };
    if (r.emailKey) addToGroup(byEmail, r.emailKey, r);
    if (r.nameKey && r.date) addToGroup(byName, r.nameKey, r);
    return r;
  });

  for (const group of byEmail.values()) {
    if (group.length < 2) continue;
    group.forEach(r => { r.dupEmail = 'DUP-email'; });

    // Newest valid timestamp wins; on ties, the lower sheet row wins.
    const dated = group.filter(r => r.date)
      .sort((a, b) => b.ms - a.ms || b.index - a.index);
    dated.slice(1).forEach(r => { r.superseded = 'SUPERSEDED'; });
  }

  for (const group of byName.values()) {
    group.sort((a, b) => a.ms - b.ms);
    for (let i = 1; i < group.length; i++) {
      if (group[i].ms - group[i - 1].ms <= WINDOW_MS) {
        group[i - 1].dupName = 'DUP-name-time';
        group[i].dupName = 'DUP-name-time';
      }
    }
  }

  const output = rows.map(r => {
    if (!r) return helperHeaders.map(() => '');
    const needsReview =
      r.joined === 'REVIEW' || r.phone === 'REVIEW' || !r.date ||
      r.park === 'REVIEW' || r.dupEmail || r.dupName;
    return [
      r.joined, r.phone, r.date || 'REVIEW', r.park, r.emailKey, r.nameKey,
      r.dupEmail, r.dupName, r.superseded, needsReview ? 'REVIEW' : 'OK'
    ];
  });

  const missing = helperHeaders.filter(header => !columns.has(header));
  if (missing.length) {
    const start = raw.getLastColumn() + 1;
    const end = start + missing.length - 1;
    if (end > raw.getMaxColumns()) {
      raw.insertColumnsAfter(raw.getMaxColumns(), end - raw.getMaxColumns());
    }
    raw.getRange(1, start, 1, missing.length).setValues([missing]);
    missing.forEach((header, i) => columns.set(header, start + i - 1));
  }

  if (!output.length) return;
  helperHeaders.forEach((header, i) => {
    const range = raw.getRange(2, columns.get(header) + 1, output.length, 1);
    if (header === 'CleanPhone') range.setNumberFormat('@');
    if (header === 'ParsedTimestamp') {
      range.setNumberFormat('yyyy-mm-dd hh:mm:ss');
    }
    // Write literal text even if a source-derived value starts with "=".
    range.setValues(output.map(row => {
      const value = row[i];
      return [typeof value === 'string' && value.startsWith('=')
        ? "'" + value : value];
    }));
  });
}
```

Put aliases like `westside`, `wside`, and `northpark` in `ParkMap!A2:A`, with the corresponding canonical names in column B. Missing email or name alone doesn’t trigger review; it just skips that duplicate check.

For duplicate emails, the latest **valid** timestamp wins; if timestamps tie, the row farther down the sheet wins. Rows with unparseable timestamps aren’t marked `SUPERSEDED`, because their order is unknown. **Every duplicate candidate still gets `REVIEW`, including the suggested keeper**, so use `Superseded` as a recommendation rather than filtering only for `OK` when building your final list.

Make these three edits to `cleanVolunteerSurvey`, then save and rerun it on `Raw`. The script will refresh the helper columns without changing your source data.

