### Install and run

1. Confirm `Raw` has headers in row 1 and the six survey columns in A:F. In `ParkMap`, put aliases or keys in column A and canonical names in B, with headers in row 1.
2. Open **Extensions → Apps Script**, replace the previous script, and save. Set the options at the top, select `runVolunteerCleaning`, and click **Run**. Authorize it if prompted. `DATE_ORDER` applies only to text dates, not dates Sheets already parsed.
3. Check `CleaningSummary`, then filter `Clean` to `Review = REVIEW`. Use `ReviewReasons` and `RawRow` to trace issues. Add approved aliases to `ParkMap` yourself and rerun. `W. Side` cleans to `wside`, not `westside`, so it appears under a separate key unless you map both keys to `West Side`.

**Each run replaces the contents of `Clean`, `Final`, `ParkCandidates`, and `CleaningSummary`.** It leaves `Raw` and `ParkMap` unchanged. `Final` still excludes blank emails and rows needing review; if the selected submission needs review, the script does not fall back to another one.

Here’s the full replacement script. `PhoneDigits` sits next to `NormalizedPhone` and is stored as plain text so all 10 digits are preserved when filtering or sorting. `PreferredParkRaw` sits immediately before `CanonicalPark`, and `CleaningSummary` counts park candidate keys without including the header row.

```javascript
const keepMostRecent = true; // true = newest; false = earliest
const WINDOW_MINUTES = 10;
const DATE_ORDER = 'MDY';    // Use 'DMY' if 3/4/21 means April 3.

function runVolunteerCleaning() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const tz = ss.getSpreadsheetTimeZone();
  const raw = ss.getSheetByName('Raw');
  const parkMap = ss.getSheetByName('ParkMap');
  if (!raw || !parkMap) throw new Error('Create Raw and ParkMap first.');

  const text = value => String(value ?? '').trim();
  const nameKey = value => text(value).toLowerCase().replace(/\s+/g, ' ');
  const parkKey = value => text(value).toLowerCase().replace(/[^a-z]/g, '');
  const months = 'jan feb mar apr may jun jul aug sep oct nov dec'.split(' ');
  const pad = n => String(n).padStart(2, '0');

  const parks = new Map();
  for (const [alias, canonical] of parkMap.getDataRange().getValues().slice(1)) {
    const key = parkKey(alias);
    const label = text(canonical);
    if (!key || !label) continue;
    if (parks.has(key) && parks.get(key) !== label) {
      throw new Error(`ParkMap has conflicting labels for "${alias}".`);
    }
    parks.set(key, label);
  }

  function getPhoneDigits(value) {
    const input = text(value);
    // Reject letters, extensions, misplaced plus signs, and other symbols.
    if (!/^\+?[\d\s().-]+$/.test(input)) return '';
    const digits = input.replace(/\D/g, '');
    const hasUSPrefix = digits.length === 11 && digits.startsWith('1');
    if (input.startsWith('+') && !hasUSPrefix) return '';
    const local = hasUSPrefix ? digits.slice(1) : digits;
    return local.length === 10 ? local : '';
  }

  function parseTimestamp(value) {
    if (value instanceof Date && Number.isFinite(value.getTime())) return value;

    const match = text(value).match(
      /^(\d{1,2}\/\d{1,2}\/(?:\d{4}|\d{2})|\d{1,2}-[a-z]{3}-\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?$/i
    );
    if (!match) return null;

    let year, month, day;
    if (match[1].includes('/')) {
      const [a, b, y] = match[1].split('/');
      [month, day] = DATE_ORDER === 'MDY' ? [+a, +b] : [+b, +a];
      year = +y + (y.length === 2 ? 2000 : 0);
    } else {
      const [d, mon, y] = match[1].split('-');
      day = +d;
      month = months.indexOf(mon.toLowerCase()) + 1;
      year = +y;
    }

    const stamp = `${year}-${pad(month)}-${pad(day)} ` +
      `${pad(+(match[2] || 0))}:${match[3] || '00'}:${match[4] || '00'}`;
    const format = 'yyyy-MM-dd HH:mm:ss';
    try {
      const date = Utilities.parseDate(stamp, tz, format);
      return Utilities.formatDate(date, tz, format) === stamp ? date : null;
    } catch (err) {
      return null;
    }
  }

  const candidates = new Map();
  const values = raw.getRange(1, 1, Math.max(1, raw.getLastRow()), 6).getValues();
  const rows = values.slice(1)
    .map((v, i) => ({ v, sourceRow: i + 2 }))
    .filter(r => r.v.some(value => text(value) !== ''))
    .map(r => {
      const [stamp, name, email, joined, phone, park] = r.v;
      const yn = text(joined).toLowerCase();
      const normalizedJoined = /^(y|yes)$/.test(yn) ? 'Yes'
                             : /^(n|no)$/.test(yn) ? 'No' : '';

      const phoneDigits = getPhoneDigits(phone);
      const normalizedPhone = phoneDigits
        ? `+1 (${phoneDigits.slice(0, 3)}) ${phoneDigits.slice(3, 6)}-${phoneDigits.slice(6)}`
        : '';

      const parsedTimestamp = parseTimestamp(stamp);
      const key = parkKey(park);
      const canonicalPark = parks.get(key) || '';
      const emailKey = text(email).toLowerCase();
      const normalizedName = nameKey(name);
      const reasons = new Set();

      if (!normalizedJoined) reasons.add('Unrecognized or missing Yes/No');
      if (!phoneDigits) reasons.add('Phone needs a 10-digit US number');
      if (!parsedTimestamp) reasons.add('Invalid or unrecognized timestamp');
      if (!canonicalPark) {
        reasons.add('Unmapped or missing park');
        if (text(park)) {
          if (!candidates.has(key)) {
            candidates.set(key, { totalCount: 0, variants: new Map() });
          }
          const entry = candidates.get(key);
          const originalValue = String(park);
          entry.totalCount++;
          entry.variants.set(originalValue, (entry.variants.get(originalValue) || 0) + 1);
        }
      }
      if (emailKey && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailKey)) {
        reasons.add('Check email format');
      }

      return {
        ...r, emailKey, normalizedName, normalizedJoined, normalizedPhone,
        phoneDigits, parsedTimestamp, preferredParkRaw: park, canonicalPark,
        reasons, dupEmail: '', dupNameTime: '', superseded: ''
      };
    });

  function groupBy(key) {
    const groups = new Map();
    for (const r of rows) {
      if (!r[key]) continue;
      if (!groups.has(r[key])) groups.set(r[key], []);
      groups.get(r[key]).push(r);
    }
    return groups;
  }

  const windowMs = WINDOW_MINUTES * 60 * 1000;
  for (const group of groupBy('normalizedName').values()) {
    for (let i = 0; i < group.length; i++) {
      const a = group[i];
      if (group.length > 1 && !a.emailKey) {
        a.reasons.add('Missing email and name appears more than once');
      }
      for (let j = i + 1; j < group.length; j++) {
        const b = group[j];
        if (!a.parsedTimestamp || !b.parsedTimestamp) continue;
        if (Math.abs(a.parsedTimestamp - b.parsedTimestamp) > windowMs) continue;
        a.dupNameTime = b.dupNameTime = 'DUP-name-time';
        if (!a.emailKey || !b.emailKey || a.emailKey !== b.emailKey) {
          a.reasons.add('Same name and close timestamp; email differs or is missing');
          b.reasons.add('Same name and close timestamp; email differs or is missing');
        }
      }
    }
  }

  const emailGroups = groupBy('emailKey');
  const finalRows = [];
  let emailDuplicates = 0;
  const direction = keepMostRecent ? -1 : 1;

  for (const group of emailGroups.values()) {
    if (group.length > 1) {
      emailDuplicates += group.length - 1;
      const signatures = new Set(group.map(r => JSON.stringify([
        r.normalizedName, r.normalizedJoined, r.phoneDigits, r.canonicalPark
      ])));
      for (const r of group) {
        r.dupEmail = 'DUP-email';
        if (signatures.size > 1) r.reasons.add('Same email, conflicting name or answers');
      }
    }

    if (group.some(r => !r.parsedTimestamp)) {
      if (group.length > 1) {
        group.forEach(r => r.reasons.add('Cannot order all submissions for this email'));
      }
      continue;
    }

    group.sort((a, b) => direction * (
      (a.parsedTimestamp - b.parsedTimestamp) || (a.sourceRow - b.sourceRow)
    ));
    group.slice(1).forEach(r => { r.superseded = 'SUPERSEDED'; });
    if (group[0].reasons.size === 0) finalRows.push(group[0]);
  }

  const headers = [
    'Timestamp', 'Name', 'Email', 'JoinedBefore', 'Phone', 'PreferredPark',
    'NormalizedJoined', 'NormalizedPhone', 'PhoneDigits', 'ParsedTimestamp',
    'PreferredParkRaw', 'CanonicalPark',
    'DUP-email', 'DUP-name-time', 'SUPERSEDED', 'Review', 'ReviewReasons', 'RawRow'
  ];

  // Prevent imported text beginning with "=" from becoming a formula.
  const literal = value =>
    typeof value === 'string' && value.startsWith('=') ? "'" + value : value;

  function writeSheet(name, output, applyFormats) {
    const sheet = ss.getSheetByName(name) || ss.insertSheet(name);
    const width = output[0].length;
    sheet.clearContents();
    if (sheet.getMaxRows() < output.length) {
      sheet.insertRowsAfter(sheet.getMaxRows(), output.length - sheet.getMaxRows());
    }
    if (sheet.getMaxColumns() < width) {
      sheet.insertColumnsAfter(sheet.getMaxColumns(), width - sheet.getMaxColumns());
    }
    if (applyFormats && output.length > 1) applyFormats(sheet, output.length - 1);
    sheet.getRange(1, 1, output.length, width).setValues(
      output.map(row => row.map(literal))
    );
    sheet.setFrozenRows(1);
  }

  function writeResponses(name, data) {
    writeSheet(name, [headers, ...data.map(r => [
      ...r.v, r.normalizedJoined, r.normalizedPhone, r.phoneDigits,
      r.parsedTimestamp || '', r.preferredParkRaw, r.canonicalPark,
      r.dupEmail, r.dupNameTime, r.superseded,
      r.reasons.size ? 'REVIEW' : 'OK', [...r.reasons].join('; '), r.sourceRow
    ])], (sheet, count) => {
      for (const header of ['Phone', 'NormalizedPhone', 'PhoneDigits', 'PreferredParkRaw']) {
        sheet.getRange(2, headers.indexOf(header) + 1, count, 1).setNumberFormat('@');
      }
      for (const header of ['Timestamp', 'ParsedTimestamp']) {
        sheet.getRange(2, headers.indexOf(header) + 1, count, 1)
          .setNumberFormat('yyyy-mm-dd hh:mm:ss');
      }
    });
  }

  const candidateRows = [...candidates.entries()]
    .sort(([keyA, a], [keyB, b]) =>
      b.totalCount - a.totalCount || keyA.localeCompare(keyB))
    .map(([key, entry]) => [
      key,
      entry.totalCount,
      [...entry.variants.entries()]
        .sort(([valueA, countA], [valueB, countB]) =>
          countB - countA || valueA.localeCompare(valueB))
        .map(([original, count]) => `${original} (${count})`)
        .join('; ')
    ]);

  writeResponses('Clean', rows);
  writeResponses('Final', finalRows.sort((a, b) => a.sourceRow - b.sourceRow));
  writeSheet('ParkCandidates', [['key', 'totalCount', 'variants'], ...candidateRows],
    (sheet, count) => {
      sheet.getRange(2, 1, count, 1).setNumberFormat('@');
      sheet.getRange(2, 2, count, 1).setNumberFormat('0');
      sheet.getRange(2, 3, count, 1).setNumberFormat('@');
    });
  writeSheet('CleaningSummary', [
    ['Metric', 'Count'],
    ['Total rows processed', rows.length],
    ['Rows flagged REVIEW', rows.filter(r => r.reasons.size > 0).length],
    ['Unique emails', emailGroups.size],
    ['Email duplicates found', emailDuplicates],
    ['Final rows kept', finalRows.length],
    ['Park candidate keys', candidateRows.length]
  ], (sheet, count) => sheet.getRange(2, 2, count, 1).setNumberFormat('0'));

  ss.toast(`${rows.length} rows cleaned; ${finalRows.length} kept in Final.`);
}
