```javascript
// ── Configuration ───────────────────────────────────────────────────────────
const CONFIG = {
  DEFAULT_AREA_CODE: "555",   // prepended to 7-digit phones; set "" to skip
  DUP_WINDOW_MINUTES: 10,    // name+timestamp proximity window
  RAW_SHEET: "Raw",
  MAP_SHEET: "ParkMap",
  CLEAN_SHEET: "Clean",
};

// ── Entry point ─────────────────────────────────────────────────────────────
function cleanVolunteerData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // --- Read sources ---
  const rawSheet = ss.getSheetByName(CONFIG.RAW_SHEET);
  if (!rawSheet) throw new Error("Sheet '" + CONFIG.RAW_SHEET + "' not found");
  const rawData = rawSheet.getDataRange().getValues();          // includes header
  const headers = rawData.shift();                               // row 0 = header

  const parkMap = buildParkMap(ss);

  // --- Normalize every row ---
  let rows = rawData.map(function (r, i) {
    return {
      _srcIndex: i,
      timestamp:      r[0],
      name:           String(r[1]).trim(),
      email:          String(r[2]).trim().toLowerCase(),
      joinedBefore:   r[3],
      phone:          String(r[4]).trim(),
      preferredPark:  String(r[5]).trim(),
      // normalised versions filled below
      nTimestamp:     normalizeTimestamp(r[0]),
      nJoined:       normalizeYesNo(r[3]),
      nPhone:        normalizePhone(r[4]),
      nPark:         normalizePark(r[5], parkMap),
      flag:          "OK",
      flagNotes:     [],
    };
  });

  // --- Flag cells that need review ---
  rows.forEach(function (r) {
    if (r.nJoined   === "REVIEW") r.flagNotes.push("YN");
    if (r.nPhone    === "REVIEW") r.flagNotes.push("Phone");
    if (r.nTimestamp === "REVIEW") r.flagNotes.push("Timestamp");
    if (r.nPark     === "REVIEW") r.flagNotes.push("Park");
    if (r.email     === "")       r.flagNotes.push("NoEmail");
  });

  // --- Deduplicate by email (keep latest) ---
  dedupeByEmail(rows);

  // --- Deduplicate by name+timestamp proximity (merge) ---
  dedupeByNameTime(rows);

  // --- Finalise flag column ---
  rows.forEach(function (r) {
    if (r.flag === "SUPERSEDED") return;
    r.flag = r.flagNotes.length > 0 ? "REVIEW" : "OK";
  });

  // --- Write Clean sheet ---
  writeCleanSheet(ss, rows);

  SpreadsheetApp.getUi().alert(
    "Done — " + rows.length + " rows processed. Check the "" +
    CONFIG.CLEAN_SHEET + "" sheet.");
}

// ── Normalizers ─────────────────────────────────────────────────────────────

function normalizeYesNo(val) {
  var s = String(val).trim().toLowerCase();
  if (/^y(es)?$/.test(s)) return "Yes";
  if (/^no?$/.test(s))    return "No";
  if (s === "")            return "";
  return "REVIEW";
}

function normalizePhone(val) {
  var digits = String(val).replace(/\D/g, "");
  if (digits.length === 11 && digits[0] === "1") digits = digits.slice(1);
  if (digits.length === 7 && CONFIG.DEFAULT_AREA_CODE) {
    digits = CONFIG.DEFAULT_AREA_CODE + digits;
  }
  if (digits.length === 10) return digits;
  if (digits === "") return "";
  return "REVIEW";
}

function normalizeTimestamp(val) {
  if (val instanceof Date && !isNaN(val)) return val;
  var d = new Date(val);
  if (!isNaN(d)) return d;
  return "REVIEW";
}

function normalizePark(val, parkMap) {
  var s = String(val).trim();
  if (s === "") return "";
  var key = s.replace(/[^a-zA-Z]/g, "").toLowerCase();
  if (parkMap.hasOwnProperty(key)) return parkMap[key];
  return "REVIEW";
}

function buildParkMap(ss) {
  var sheet = ss.getSheetByName(CONFIG.MAP_SHEET);
  if (!sheet) throw new Error("Sheet '" + CONFIG.MAP_SHEET + "' not found");
  var data = sheet.getDataRange().getValues();
  var map = {};
  data.forEach(function (r) {
    var key = String(r[0]).replace(/[^a-zA-Z]/g, "").toLowerCase();
    if (key) map[key] = String(r[1]).trim();
  });
  return map;
}

// ── Deduplication ───────────────────────────────────────────────────────────

function dedupeByEmail(rows) {
  // Group rows by non-empty email
  var groups = {};
  rows.forEach(function (r, i) {
    if (!r.email) return;
    if (!groups[r.email]) groups[r.email] = [];
    groups[r.email].push(i);
  });

  Object.keys(groups).forEach(function (email) {
    var idxs = groups[email];
    if (idxs.length < 2) return;

    // Find the row with the latest valid timestamp
    var bestIdx = idxs[0];
    var bestTime = -Infinity;
    idxs.forEach(function (i) {
      var t = rows[i].nTimestamp;
      var ms = (t instanceof Date) ? t.getTime() : -Infinity;
      if (ms > bestTime) { bestTime = ms; bestIdx = i; }
    });

    idxs.forEach(function (i) {
      if (i !== bestIdx) {
        rows[i].flag = "SUPERSEDED";
        rows[i].flagNotes = ["DupEmail"];
      }
    });
    rows[bestIdx].flagNotes.push("DupEmail-kept");
  });
}

function dedupeByNameTime(rows) {
  var windowMs = CONFIG.DUP_WINDOW_MINUTES * 60 * 1000;

  // Build name groups (only among non-superseded rows)
  var groups = {};
  rows.forEach(function (r, i) {
    if (r.flag === "SUPERSEDED") return;
    var nk = nameKey(r.name);
    if (!nk) return;
    if (!groups[nk]) groups[nk] = [];
    groups[nk].push(i);
  });

  Object.keys(groups).forEach(function (nk) {
    var idxs = groups[nk];
    if (idxs.length < 2) return;

    // Sort by timestamp ascending
    idxs.sort(function (a, b) {
      return tsMs(rows[a].nTimestamp) - tsMs(rows[b].nTimestamp);
    });

    // Walk through, cluster rows within the window
    var used = {};
    for (var i = 0; i < idxs.length; i++) {
      if (used[idxs[i]]) continue;
      var cluster = [idxs[i]];
      var baseMs = tsMs(rows[idxs[i]].nTimestamp);
      if (baseMs === -1) continue;

      for (var j = i + 1; j < idxs.length; j++) {
        if (used[idxs[j]]) continue;
        var cmp = tsMs(rows[idxs[j]].nTimestamp);
        if (cmp === -1) continue;
        if (cmp - baseMs <= windowMs) {
          cluster.push(idxs[j]);
        }
      }
      if (cluster.length < 2) continue;

      // Merge: keep last row, fill blanks from earlier rows
      var keepIdx = cluster[cluster.length - 1];
      var keep = rows[keepIdx];
      for (var k = 0; k < cluster.length - 1; k++) {
        var donor = rows[cluster[k]];
        mergeRow(keep, donor);
        donor.flag = "SUPERSEDED";
        donor.flagNotes = ["DupNameTime"];
        used[cluster[k]] = true;
      }
      keep.flagNotes.push("DupNameTime-merged");
    }
  });
}

/** Copies non-empty normalised fields from donor into target when target is empty. */
function mergeRow(target, donor) {
  if (!target.email && donor.email)                       target.email = donor.email;
  if (!target.nJoined && donor.nJoined)                   target.nJoined = donor.nJoined;
  if (target.nPhone === "REVIEW" && donor.nPhone !== "REVIEW" && donor.nPhone)
    target.nPhone = donor.nPhone;
  if (target.nPark  === "REVIEW" && donor.nPark  !== "REVIEW" && donor.nPark)
    target.nPark = donor.nPark;
  if (target.nTimestamp === "REVIEW" && donor.nTimestamp instanceof Date)
    target.nTimestamp = donor.nTimestamp;
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function nameKey(name) {
  return String(name).replace(/[^a-zA-Z]/g, "").toLowerCase();
}

function tsMs(ts) {
  return (ts instanceof Date) ? ts.getTime() : -1;
}

// ── Output ──────────────────────────────────────────────────────────────────

function writeCleanSheet(ss, rows) {
  var sheet = ss.getSheetByName(CONFIG.CLEAN_SHEET);
  if (sheet) {
    sheet.clear();
  } else {
    sheet = ss.insertSheet(CONFIG.CLEAN_SHEET);
  }

  var header = [
    "Timestamp", "Name", "Email", "JoinedBefore", "Phone", "PreferredPark",
    "Clean_Timestamp", "Clean_Joined", "Clean_Phone", "Clean_Park",
    "Flag", "FlagNotes"
  ];
  sheet.appendRow(header);

  var out = rows.map(function (r) {
    return [
      r.timestamp,
      r.name,
      r.email,
      r.joinedBefore,
      r.phone,
      r.preferredPark,
      r.nTimestamp,
      r.nJoined,
      r.nPhone,
      r.nPark,
      r.flag,
      r.flagNotes.join("; "),
    ];
  });

  if (out.length > 0) {
    sheet.getRange(2, 1, out.length, header.length).setValues(out);
  }

  // Formatting
  sheet.setFrozenRows(1);
  sheet.getRange(1, 1, 1, header.length).setFontWeight("bold");
  sheet.autoResizeColumns(1, header.length);

  // Colour-code flag column (K)
  var flagRange = sheet.getRange(2, 11, out.length, 1);
  var flagVals  = flagRange.getValues();
  for (var i = 0; i < flagVals.length; i++) {
    var color = null;
    if (flagVals[i][0] === "SUPERSEDED") color = "#f4cccc";  // light red
    else if (flagVals[i][0] === "REVIEW") color = "#fff2cc";  // light yellow
    else                                  color = "#d9ead3";  // light green
    sheet.getRange(i + 2, 1, 1, header.length).setBackground(color);
  }
}
