  const seen = new Set(nameTimePairs);
  seen.forEach(idx => {
    const root = ufFind(idx);
    if (!nameTimeClusters[root]) nameTimeClusters[root] = [];
    nameTimeClusters[root].push(idx);
  });

  return { emailGroups, nameTimeGroups: nameTimeClusters };
}

