  let skippedCount = 0;
  const enriched = [];

  rows.forEach((r, i) => {
    if (supersededCol >= 0) {
      const val = String(r[supersededCol]).trim().toLowerCase();
      if (val === "superseded") {
        skippedCount++;
        return;
      }
    }

    const phoneCleaned = normalizePhone(r[col.phone]);
    const ts           = parseTs(r[col.timestamp]);
    const nameTrimmed  = String(r[col.name]).trim();
    const emailLower   = String(r[col.email]).trim().toLowerCase();
    const joinedRaw    = String(r[col.joined]).trim();
    const parkRaw      = String(r[col.park]).trim();

    const issues = [];
    if (!ts)                                       issues.push("timestamp");
    if (!phoneCleaned)                             issues.push("phone");
    if (parkRaw === "" || parkRaw === "REVIEW")    issues.push("park");
    if (joinedRaw === "REVIEW")                    issues.push("joined");

    enriched.push({
      srcRow:    i + CONFIG.headerRow + 1,
      ts,
      name:      nameTrimmed,
      email:     emailLower,
      joined:    joinedRaw,
      phone:     phoneCleaned,
      phoneFail: !phoneCleaned,
      park:      parkRaw,
      issues,
      raw:       r,
    });
  });

  // ── Group rows ──────────────────────────────────────────────
  const emailGroups = {};
  const noEmailRows = [];

  enriched.forEach(r => {
    if (r.email) {
      if (!emailGroups[r.email]) emailGroups[r.email] = [];
      emailGroups[r.email].push(r);
    } else {
      noEmailRows.push(r);
    }
  });

  const namePhoneGroups = {};
  const ungroupable     = [];

  noEmailRows.forEach(r => {
    const nameKey  = r.name.toLowerCase().replace(/\s+/g, " ");
    const phoneKey = r.phone;
    if (nameKey && phoneKey) {
      const key = nameKey + "|" + phoneKey;
      if (!namePhoneGroups[key]) namePhoneGroups[key] = [];
      namePhoneGroups[key].push(r);
    } else {
      ungroupable.push(r);
    }
  });

  // ── Merge logic ─────────────────────────────────────────────
  function mergeGroup(group) {
    let bestTs = null;
    group.forEach(r => {
      if (r.ts && (!bestTs || r.ts > bestTs)) bestTs = r.ts;
    });

    let bestName = "";
    group.forEach(r => {
      if (r.name.length > bestName.length) bestName = r.name;
    });

    let bestEmail = "";
    group.forEach(r => { if (r.email && !bestEmail) bestEmail = r.email; });

    let joined = "No";
    group.forEach(r => {
      if (r.joined === "Yes") joined = "Yes";
    });

    let bestPhone   = "";
    let bestPhoneTs = null;
    group.forEach(r => {
      if (r.phone) {
        if (!bestPhoneTs || (r.ts && r.ts > bestPhoneTs)) {
          bestPhone   = r.phone;
          bestPhoneTs = r.ts;
        }
      }
    });

    let bestPark   = "";
    let bestParkTs = null;
    group.forEach(r => {
      if (r.park && r.park !== "REVIEW") {
        if (!bestParkTs || (r.ts && r.ts > bestParkTs)) {
          bestPark   = r.park;
          bestParkTs = r.ts;
        }
      }
    });

    const issues = [];
    if (!bestTs)                             issues.push("timestamp");
    if (!bestPhone)                          issues.push("phone");
    if (!bestPark || bestPark === "REVIEW")  issues.push("park");
    if (joined === "REVIEW")                 issues.push("joined");

    return {
      row:     [bestTs, bestName, bestEmail, joined, bestPhone, bestPark],
      issues,
      srcRows: group.map(r => r.srcRow),
      rawRows: group.map(r => r.raw),
    };
  }

  // ── Run merge on every group ────────────────────────────────
  const mergedResults = [];
  const reviewResults = [];
  let   namePhoneGroupedCount = 0;

  function routeResult(result) {
    if (result.issues.length > 0) {
      reviewResults.push(result);
    } else {
      mergedResults.push(result);
    }
  }

  for (const key in emailGroups) {
    routeResult(mergeGroup(emailGroups[key]));
  }

  for (const key in namePhoneGroups) {
    const g = namePhoneGroups[key];
    if (g.length > 1) namePhoneGroupedCount += g.length;
    routeResult(mergeGroup(g));
  }

  ungroupable.forEach(r => routeResult(mergeGroup([r])));

  // ── Sort both lists by name ─────────────────────────────────
  const byName = (a, b) => String(a.row[1]).localeCompare(String(b.row[1]));
  mergedResults.sort(byName);
  reviewResults.sort(byName);

  // ── Helper: remove a sheet if it exists ─────────────────────
  function removeSheet(name) {
    const s = ss.getSheetByName(name);
    if (s) ss.deleteSheet(s);
  }

  // ── Helper: get or create a sheet (cleared if exists) ───────
  function freshSheet(name) {
    let sheet = ss.getSheetByName(name);
    if (sheet) {
      sheet.clear();
    } else {
      sheet = ss.insertSheet(name);
    }
    return sheet;
  }

  // ── Write Merged sheet ──────────────────────────────────────
  if (mergedResults.length > 0) {
    const mergedHeaders = [
      "Timestamp", "Name", "Email", "JoinedBefore",
      "Phone", "PreferredPark", "SourceRows"
    ];

    const sheet = freshSheet(CONFIG.outputMerged);
    sheet.appendRow(mergedHeaders);

    const output = mergedResults.map(r => {
      const base = r.row.slice();
      base.push(r.srcRows.join(", "));
      return base;
    });

    sheet.getRange(2, 1, output.length, output[0].length).setValues(output);
    sheet.getRange(2, 1, output.length, 1).setNumberFormat("m/d/yyyy hh:mm");
    sheet.getRange(2, 5, output.length, 1).setNumberFormat("@");
    sheet.autoResizeColumns(1, mergedHeaders.length);
  } else {
    removeSheet(CONFIG.outputMerged);
  }

  // ── Write Review sheet ──────────────────────────────────────
  if (reviewResults.length > 0) {
    // Build headers: merged cols, Issues, SourceRows, then original cols
    const srcHeaders = headers.map(h => "src: " + h);
    const reviewHeaders = [
      "Timestamp", "Name", "Email", "JoinedBefore",
      "Phone", "PreferredPark", "Issues", "SourceRows"
    ].concat(srcHeaders);

    const sheet = freshSheet(CONFIG.outputReview);
    sheet.appendRow(reviewHeaders);

    // Each source row in the group gets its own output row so
    // you can see every original submission side by side.
    const output = [];
    reviewResults.forEach(r => {
      const base = r.row.slice();
      base.push(r.issues.join(", "));
      base.push(r.srcRows.join(", "));

      r.rawRows.forEach((raw, idx) => {
        const line = base.slice();
        // Pad with raw values from this source row
        for (let c = 0; c < srcColCount; c++) {
          line.push(raw[c] !== undefined ? raw[c] : "");
        }
        output.push(line);
      });
    });

    sheet.getRange(2, 1, output.length, output[0].length).setValues(output);
    sheet.getRange(2, 1, output.length, 1).setNumberFormat("m/d/yyyy hh:mm");
    sheet.getRange(2, 5, output.length, 1).setNumberFormat("@");
    sheet.autoResizeColumns(1, reviewHeaders.length);
  } else {
    removeSheet(CONFIG.outputReview);
  }

  // ── Write Summary sheet ─────────────────────────────────────
  if (mergedResults.length > 0 || reviewResults.length > 0 || skippedCount > 0) {
    const parkCounts = {};
    mergedResults.forEach(r => {
      const park = r.row[5] || "(blank)";
      parkCounts[park] = (parkCounts[park] || 0) + 1;
    });

    const parkNames = Object.keys(parkCounts).sort();
    const sheet = freshSheet(CONFIG.outputSummary);

    sheet.appendRow(["Merged Rows by PreferredPark"]);
    sheet.appendRow([""]);
    sheet.appendRow(["PreferredPark", "Count"]);

    if (parkNames.length > 0) {
      const summaryRows = parkNames.map(p => [p, parkCounts[p]]);
      sheet.getRange(4, 1, summaryRows.length, 2).setValues(summaryRows);
    }

    const totalRow = 4 + parkNames.length;
    sheet.getRange(totalRow, 1, 1, 2)
      .setValues([["Total Merged", mergedResults.length]])
      .setFontWeight("bold");

    sheet.getRange(totalRow + 2, 1, 1, 2)
      .setValues([["Rows sent to Review", reviewResults.length]]);
    sheet.getRange(totalRow + 3, 1, 1, 2)
      .setValues([["Rows skipped (SUPERSEDED)", skippedCount]]);

    sheet.autoResizeColumns(1, 2);
  } else {
    removeSheet(CONFIG.outputSummary);
  }

  // ── Summary alert ───────────────────────────────────────────
  const sheetsCreated = [];
  if (mergedResults.length > 0) sheetsCreated.push(CONFIG.outputMerged);
  if (reviewResults.length > 0) sheetsCreated.push(CONFIG.outputReview);
  if (mergedResults.length > 0 || reviewResults.length > 0 || skippedCount > 0) {
    sheetsCreated.push(CONFIG.outputSummary);
  }

  const ui = SpreadsheetApp.getUi();
  ui.alert(
    "Dedupe & Merge complete\n"
    + "─────────────────────────\n"
    + "Merged (clean):        " + mergedResults.length + " rows\n"
    + "Review (needs fixes):  " + reviewResults.length + " rows\n"
    + "Skipped (SUPERSEDED):  " + skippedCount + " rows\n"
    + "Blank-email rows grouped\n"
    + "  by Name+Phone:       " + namePhoneGroupedCount + " rows collapsed\n"
    + "\nSheets created: " + (sheetsCreated.length > 0
        ? sheetsCreated.map(function(n) { return '"' + n + '"'; }).join(", ")
        : "(none — no data to write)")
  );
}
