const DRY_RUN = true; // flip to false when ready

function cleanAndConsolidate() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // ── Load raw data ──
  const raw = ss.getSheetByName("Raw");
  if (!raw) throw new Error("Sheet 'Raw' not found");
  const data = raw.getDataRange().getValues(); // [row][col]
  const headers = data[0];
  const colIdx = {}; // header → index
  headers.forEach((h, i) => colIdx[h.toString().trim()] = i);

  // Expect these columns (case-sensitive as typed in your sheet)
  const C = {
    ts:   colIdx["Timestamp"],
    name: colIdx["Name"],
    email:colIdx["Email"],
    yesno:colIdx["JoinedBefore"],
    phone:colIdx["Phone"],
    park: colIdx["PreferredPark"]
  };

  // ── Load ParkMap ──
  const pmSheet = ss.getSheetByName("ParkMap");
  if (!pmSheet) throw new Error("Sheet 'ParkMap' not found");
  const parkMap = {};
  pmSheet.getDataRange().getValues().forEach(r => {
    if (r[0] !== "") parkMap[String(r[0]).toLowerCase().replace(/[^a-z]/g, "")] = r[1];
  });

  // ── Helpers ──

  /** Strip to digits, drop leading-1 country code. Returns string or "REVIEW". */
  function cleanPhone(val) {
    if (val == null || String(val).trim() === "") return "";
    let digits = String(val).replace(/\D/g, "");
    if (digits.length === 11 && digits[0] === "1") digits = digits.slice(1);
    return digits.length === 10 ? digits : "REVIEW";
  }

  /** Try to coerce a value to a JS Date. Returns Date or null. */
  function cleanTimestamp(val) {
    if (val instanceof Date && !isNaN(val)) return val;
    if (val == null || String(val).trim() === "") return null;
    const d = new Date(String(val));
    return isNaN(d) ? null : d;
  }

  /** Normalize yes/no. */
  function cleanYesNo(val) {
    const v = String(val).trim().toLowerCase();
    if (/^y(es)?$/.test(v)) return "Yes";
    if (/^no?$/.test(v)) return "No";
    if (v === "") return "";
    return "REVIEW";
  }

  /** Map park name via ParkMap. */
  function cleanPark(val) {
    if (val == null || String(val).trim() === "") return "";
    const key = String(val).toLowerCase().replace(/[^a-z]/g, "");
    return parkMap[key] || "REVIEW";
  }

  // ── Clean each row ──
  const rows = []; // {orig row#, cleaned fields, issues[]}
  for (let i = 1; i < data.length; i++) {
    const r = data[i];
    const ts    = cleanTimestamp(r[C.ts]);
    const phone = cleanPhone(r[C.phone]);
    const yesno = cleanYesNo(r[C.yesno]);
    const park  = cleanPark(r[C.park]);
    const email = String(r[C.email] || "").trim().toLowerCase();
    const name  = String(r[C.name]  || "").trim();

    const issues = [];
    if (ts === null && String(r[C.ts]).trim() !== "") issues.push("bad-timestamp");
    if (phone === "REVIEW") issues.push("bad-phone");
    if (yesno === "REVIEW") issues.push("bad-yesno");
    if (park  === "REVIEW") issues.push("unmapped-park");
    if (email === "")       issues.push("no-email");

    rows.push({
      srcRow: i + 1, // 1-based sheet row
      ts, name, email, yesno, phone, park, issues
    });
  }

  // ── Consolidate by email ──
  const byEmail = {};   // email → [row objects]
  const noEmail = [];   // rows without email go straight through
  rows.forEach(r => {
    if (r.email === "") { noEmail.push(r); return; }
    (byEmail[r.email] = byEmail[r.email] || []).push(r);
  });

  /**
   * Merge a group: keep the latest-timestamp row, fill blanks from older rows.
   * Returns one consolidated object.
   */
  function mergeGroup(group) {
    // Sort descending by timestamp (nulls last)
    group.sort((a, b) => ((b.ts ? b.ts.getTime() : 0) - (a.ts ? a.ts.getTime() : 0)));

    const best = Object.assign({}, group[0]); // shallow copy of latest
    best.srcRows = group.map(r => r.srcRow);
    best.merged  = group.length > 1;

    // Collect all issues from every row in the group
    const allIssues = new Set();
    best.issues.forEach(i => allIssues.add(i));

    // Fill blanks from older rows
    const fields = ["name", "phone", "yesno", "park"];
    for (let i = 1; i < group.length; i++) {
      group[i].issues.forEach(iss => allIssues.add(iss));
      fields.forEach(f => {
        if ((best[f] === "" || best[f] === "REVIEW") &&
            group[i][f] !== "" && group[i][f] !== "REVIEW") {
          best[f] = group[i][f];
          allIssues.delete(
            f === "phone" ? "bad-phone" :
            f === "yesno" ? "bad-yesno" :
            f === "park"  ? "unmapped-park" : ""
          );
        }
      });
      // Fill timestamp if best is null
      if (best.ts === null && group[i].ts !== null) {
        best.ts = group[i].ts;
        allIssues.delete("bad-timestamp");
      }
    }
    best.issues = [...allIssues];
    return best;
  }

  const output = [];

  // Process email groups
  Object.values(byEmail).forEach(group => {
    output.push(mergeGroup(group));
  });

  // No-email rows pass through individually
  noEmail.forEach(r => {
    r.srcRows = [r.srcRow];
    r.merged = false;
    output.push(r);
  });

  // Sort output by timestamp ascending
  output.sort((a, b) => ((a.ts ? a.ts.getTime() : 0) - (b.ts ? b.ts.getTime() : 0)));

  // ── Determine status ──
  output.forEach(r => {
    if (r.issues.length > 0) {
      r.status = "REVIEW";
    } else if (r.merged) {
      r.status = "MERGED";
    } else {
      r.status = "KEPT";
    }
  });

  // ── Build output array ──
  const outHeaders = ["Timestamp", "Name", "Email", "JoinedBefore",
                      "Phone", "PreferredPark", "SourceRows", "Status", "Issues"];
  const outData = output.map(r => [
    r.ts || "",
    r.name,
    r.email,
    r.yesno,
    r.phone,
    r.park,
    r.srcRows.join(", "),
    r.status,
    r.issues.join("; ")
  ]);

  // ── Write or log ──
  if (DRY_RUN) {
    Logger.log("DRY RUN — " + outData.length + " consolidated rows");
    Logger.log(outHeaders.join(" | "));
    outData.slice(0, 20).forEach((row, i) => Logger.log(row.join(" | ")));
    if (outData.length > 20) Logger.log("... (" + (outData.length - 20) + " more rows)");
    SpreadsheetApp.getUi().alert(
      "Dry run complete: " + outData.length + " rows. Check View → Logs.");
  } else {
    let prev = ss.getSheetByName("Consolidated-preview");
    if (prev) ss.deleteSheet(prev);
    prev = ss.insertSheet("Consolidated-preview");
    prev.appendRow(outHeaders);
    if (outData.length) {
      prev.getRange(2, 1, outData.length, outHeaders.length).setValues(outData);
    }
    // Format timestamp column as datetime
    prev.getRange(2, 1, Math.max(outData.length, 1), 1)
        .setNumberFormat("yyyy-mm-dd hh:mm");
    // Auto-resize
    outHeaders.forEach((_, i) => prev.autoResizeColumn(i + 1));
    SpreadsheetApp.getUi().alert(
      "Done! " + outData.length + " rows written to Consolidated-preview.");
  }
}

