## How to use it

1. **Extensions → Apps Script**, paste the code, save.
2. Reload the spreadsheet — a **🧹 Cleaning** menu appears.
3. Leave `DRY_RUN = true` and run. Check **View → Logs** (in the script editor) to inspect the first 20 consolidated rows.
4. When you're happy, set `DRY_RUN = false` and run again. It creates (or replaces) `Consolidated-preview`.

## What happens to your sample rows

| SourceRows | Result | Why |
|---|---|---|
| 2, 3 (Maya Singh) | **MERGED + REVIEW** | Same email → kept row 2 (latest timestamp is a tie, so first encountered). Phone is 7 digits on both → `bad-phone` stays. |
| 4 (Tom Zhao) | **REVIEW** | No email → passes through solo. 7-digit phone → `bad-phone`. |
| 5 (A. Rivera) | **REVIEW** | Solo email group. 7-digit phone → `bad-phone`. |

All four sample rows flag on phone because they're all 7 digits — exactly the issue you spotted earlier. Once you confirm an area code and update `Raw`, re-run and those flags clear.

## Key design decisions

- **Merge fill order:** Latest timestamp wins; blanks/REVIEWs are back-filled from older duplicates. If an older row has a valid phone and the newest doesn't, the valid phone is used and the `bad-phone` issue is removed.
- **No-email rows** can't be de-duped by email, so they pass through individually and get flagged `no-email` for manual review.
- **Raw is never touched.** The script only reads from it.
- **Re-runnable:** Running again with `DRY_RUN = false` deletes the old preview sheet and rebuilds it.

```javascript
/**
 * Volunteer Survey Cleaner v2
 * Run: cleanAndConsolidate()
 */

const DRY_RUN = true;           // flip to false when ready
const NAME_WINDOW_MIN = 10;     // minutes for name+timestamp matching

function cleanAndConsolidate() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // ── Load raw data ──
  const raw = ss.getSheetByName("Raw");
  if (!raw) throw new Error("Sheet 'Raw' not found");
  const data = raw.getDataRange().getValues();
  const headers = data[0];
  const colIdx = {};
  headers.forEach((h, i) => colIdx[h.toString().trim()] = i);

  const C = {
    ts:   colIdx["Timestamp"],
    name: colIdx["Name"],
    email:colIdx["Email"],
    yesno:colIdx["JoinedBefore"],
    phone:colIdx["Phone"],
    park: colIdx["PreferredPark"]
  };

  // ── Load ParkMap ──
  const pmSheet = ss.getSheetByName("ParkMap");
  if (!pmSheet) throw new Error("Sheet 'ParkMap' not found");
  const parkMap = {};
  pmSheet.getDataRange().getValues().forEach(r => {
    if (r[0] !== "") parkMap[String(r[0]).toLowerCase().replace(/[^a-z]/g, "")] = r[1];
  });

  // ── Helpers ──

  function cleanPhone(val) {
    if (val == null || String(val).trim() === "") return "";
    let digits = String(val).replace(/\D/g, "");
    if (digits.length === 11 && digits[0] === "1") digits = digits.slice(1);
    return digits.length === 10 ? digits : "REVIEW";
  }

  function cleanTimestamp(val) {
    if (val instanceof Date && !isNaN(val)) return val;
    if (val == null || String(val).trim() === "") return null;
    const d = new Date(String(val));
    return isNaN(d) ? null : d;
  }

  function cleanYesNo(val) {
    const v = String(val).trim().toLowerCase();
    if (/^y(es)?$/.test(v)) return "Yes";
    if (/^no?$/.test(v))    return "No";
    return v === "" ? "" : "REVIEW";
  }

  function cleanPark(val) {
    if (val == null || String(val).trim() === "") return "";
    const key = String(val).toLowerCase().replace(/[^a-z]/g, "");
    return parkMap[key] || "REVIEW";
  }

  /** Normalize name for comparison: lowercase, collapse whitespace, strip periods */
  function normName(val) {
    return String(val || "").trim().toLowerCase()
      .replace(/\./g, "").replace(/\s+/g, " ");
  }

  // ── Clean each row ──
  const rows = [];
  for (let i = 1; i < data.length; i++) {
    const r = data[i];
    const ts    = cleanTimestamp(r[C.ts]);
    const phone = cleanPhone(r[C.phone]);
    const yesno = cleanYesNo(r[C.yesno]);
    const park  = cleanPark(r[C.park]);
    const email = String(r[C.email] || "").trim().toLowerCase();
    const name  = String(r[C.name]  || "").trim();

    const issues = [];
    if (ts === null && String(r[C.ts]).trim() !== "") issues.push("bad-timestamp");
    if (phone === "REVIEW") issues.push("bad-phone");
    if (yesno === "REVIEW") issues.push("bad-yesno");
    if (park  === "REVIEW") issues.push("unmapped-park");
    if (email === "")       issues.push("no-email");

    rows.push({
      srcRow: i + 1,
      ts, name, email, yesno, phone, park, issues,
      normName: normName(name),
      // Store original raw values for the RawValues column
      rawStr: r.map(c => {
        if (c instanceof Date) {
          // Format dates readably
          return Utilities.formatDate(c, ss.getSpreadsheetTimeZone(), "yyyy-MM-dd HH:mm");
        }
        return String(c);
      }).join(" | ")
    });
  }

  // ── Phase 1: Group by email ──
  const byEmail = {};
  const ungrouped = [];  // rows not consumed by email grouping

  rows.forEach(r => {
    if (r.email === "") { ungrouped.push(r); return; }
    (byEmail[r.email] = byEmail[r.email] || []).push(r);
  });

  /**
   * Merge a group: keep latest timestamp, backfill blanks from older rows.
   * Returns one consolidated object.
   */
  function mergeGroup(group, matchType) {
    // Sort descending by timestamp (nulls last)
    group.sort((a, b) => ((b.ts ? b.ts.getTime() : 0) - (a.ts ? a.ts.getTime() : 0)));

    const best = Object.assign({}, group[0]);
    best.srcRows  = group.map(r => r.srcRow);
    best.merged   = group.length > 1;
    best.matchType = matchType;
    // Collect all raw strings
    best.rawStrs  = group.map(r => "Row " + r.srcRow + ": " + r.rawStr);

    const allIssues = new Set(best.issues);

    const fields = ["name", "phone", "yesno", "park", "email"];
    const issueMap = {
      phone: "bad-phone", yesno: "bad-yesno",
      park: "unmapped-park", email: "no-email"
    };

    for (let i = 1; i < group.length; i++) {
      group[i].issues.forEach(iss => allIssues.add(iss));
      fields.forEach(f => {
        if ((best[f] === "" || best[f] === "REVIEW") &&
            group[i][f] !== "" && group[i][f] !== "REVIEW") {
          best[f] = group[i][f];
          if (issueMap[f]) allIssues.delete(issueMap[f]);
        }
      });
      if (best.ts === null && group[i].ts !== null) {
        best.ts = group[i].ts;
        allIssues.delete("bad-timestamp");
      }
    }
    best.issues = [...allIssues];
    return best;
  }

  const output = [];

  // Process email groups
  Object.values(byEmail).forEach(group => {
    output.push(mergeGroup(group, "email"));
  });

  // ── Phase 2: Name+timestamp grouping on ungrouped rows ──
  // Union-Find to cluster rows with matching name within the time window

  const parent = ungrouped.map((_, i) => i);
  function find(x) { return parent[x] === x ? x : (parent[x] = find(parent[x])); }
  function union(a, b) { parent[find(a)] = find(b); }

  const windowMs = NAME_WINDOW_MIN * 60 * 1000;

  // Build buckets by normalized name for efficiency
  const nameIdx = {};
  ungrouped.forEach((r, i) => {
    if (r.normName === "") return;
    (nameIdx[r.normName] = nameIdx[r.normName] || []).push(i);
  });

  // Within each name bucket, pair rows whose timestamps are within the window
  Object.values(nameIdx).forEach(idxs => {
    for (let a = 0; a < idxs.length; a++) {
      for (let b = a + 1; b < idxs.length; b++) {
        const tA = ungrouped[idxs[a]].ts;
        const tB = ungrouped[idxs[b]].ts;
        if (tA && tB && Math.abs(tA.getTime() - tB.getTime()) <= windowMs) {
          union(idxs[a], idxs[b]);
        }
      }
    }
  });

  // Collect clusters
  const clusters = {};
  ungrouped.forEach((_, i) => {
    const root = find(i);
    (clusters[root] = clusters[root] || []).push(ungrouped[i]);
  });

  Object.values(clusters).forEach(group => {
    const matchType = group.length > 1 ? "name-time" : "none";
    output.push(mergeGroup(group, matchType));
  });

  // Sort output by timestamp ascending
  output.sort((a, b) => ((a.ts ? a.ts.getTime() : 0) - (b.ts ? b.ts.getTime() : 0)));

  // ── Determine status ──
  output.forEach(r => {
    if (r.issues.length > 0)       r.status = "REVIEW";
    else if (r.merged)             r.status = "MERGED";
    else                           r.status = "KEPT";
  });

  // ── Build output array ──
  const outHeaders = [
    "Timestamp", "Name", "Email", "JoinedBefore", "Phone",
    "PreferredPark", "SourceRows", "MatchType", "Status", "Issues", "RawValues"
  ];

  const tz = ss.getSpreadsheetTimeZone();
  const outData = output.map(r => [
    r.ts || "",
    r.name,
    r.email,
    r.yesno,
    r.phone,
    r.park,
    r.srcRows.join(", "),
    r.matchType,
    r.status,
    r.issues.join("; "),
    r.rawStrs.join("\n")
  ]);

  // ── Write or log ──
  if (DRY_RUN) {
    Logger.log("DRY RUN — " + outData.length + " consolidated rows");
    Logger.log(outHeaders.join(" | "));
    outData.slice(0, 25).forEach(row => Logger.log(row.join(" | ")));
    if (outData.length > 25) Logger.log("... (" + (outData.length - 25) + " more rows)");
    SpreadsheetApp.getUi().alert(
      "Dry run complete: " + outData.length + " rows.\nCheck View → Logs.");
  } else {
    let prev = ss.getSheetByName("Consolidated-preview");
    if (prev) ss.deleteSheet(prev);
    prev = ss.insertSheet("Consolidated-preview");
    prev.appendRow(outHeaders);
    if (outData.length) {
      prev.getRange(2, 1, outData.length, outHeaders.length).setValues(outData);
    }
    prev.getRange(2, 1, Math.max(outData.length, 1), 1)
        .setNumberFormat("yyyy-mm-dd hh:mm");
    // Wrap the RawValues column so multi-line content is visible
    prev.getRange(2, outHeaders.length, Math.max(outData.length, 1), 1)
        .setWrapStrategy(SpreadsheetApp.WrapStrategy.WRAP);
    outHeaders.forEach((_, i) => prev.autoResizeColumn(i + 1));
    SpreadsheetApp.getUi().alert(
      "Done! " + outData.length + " rows written to Consolidated-preview.");
  }
}

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("🧹 Cleaning")
    .addItem("Run consolidation", "cleanAndConsolidate")
    .addToUi();
}
