  const parts = rowNumbers.map(String);
  const separator = ', ';
  const fullText = parts.join(separator);

  const builder = SpreadsheetApp.newRichTextValue().setText(fullText);

  let cursor = 0;
  parts.forEach((piece, idx) => {
    const start = cursor;
    const end = cursor + piece.length;
    const url = `${ssUrl}#gid=${cleanGid}&range=A${piece}`;
    builder.setLinkUrl(start, end, url);
    cursor = end;
    if (idx < parts.length - 1) cursor += separator.length;
  });

  return builder.build();
}

function writeFinal(ss, rows, ssUrl, cleanGid) {
  let sheet = ss.getSheetByName(TARGET_SHEET);
  if (!sheet) sheet = ss.insertSheet(TARGET_SHEET);
  sheet.clear();

  const headers = [
    'Key', 'Timestamp', 'SOURCE_ROWS',
    'Name',         'Name_values',
    'Email',        'Email_values',
    'JoinedBefore', 'JoinedBefore_values',
    'Phone',        'Phone_values',
    'Park',         'Park_values',
    'CONFLICTS',
  ];
  sheet.getRange(1, 1, 1, headers.length).setValues([headers]).setFontWeight('bold');
  sheet.setFrozenRows(1);

  if (rows.length === 0) return;

  const srcColIdx = headers.indexOf('SOURCE_ROWS'); // 0-based

  // Write plain values first (SOURCE_ROWS column gets empty strings; replaced below).
  const values = rows.map(r => headers.map((h, i) => {
    if (i === srcColIdx) return '';
    return r[h] !== undefined ? r[h] : '';
  }));
  sheet.getRange(2, 1, values.length, headers.length).setValues(values);

  // Now set SOURCE_ROWS as RichText per cell.
  const richValues = rows.map(r => [
    buildSourceRowsRichText(r.SOURCE_ROWS || [], ssUrl, cleanGid),
  ]);
  sheet.getRange(2, srcColIdx + 1, rows.length, 1).setRichTextValues(richValues);

  // Formatting
  const tsCol = headers.indexOf('Timestamp') + 1;
  sheet.getRange(2, tsCol, values.length, 1).setNumberFormat('yyyy-mm-dd hh:mm');

  const phoneCol = headers.indexOf('Phone') + 1;
  const phoneValsCol = headers.indexOf('Phone_values') + 1;
  sheet.getRange(2, phoneCol, values.length, 1).setNumberFormat('@');
  sheet.getRange(2, phoneValsCol, values.length, 1).setNumberFormat('@');

  sheet.getRange(2, srcColIdx + 1, values.length, 1).setNumberFormat('@');

  sheet.autoResizeColumns(1, headers.length);
}
