/**
 * Dedupe Responses by email and write merged rows to Final_Merged.
 *
 * Rules:
 *  - Rows with the same email (case and space insensitive) are one group.
 *  - Keeper = newest timestamp; on a tie, the lower sheet row wins.
 *  - Blank fields on the keeper are filled from other rows (newest first).
 *  - Conflicts lists fields where rows in the group have different non-blank values.
 *  - Rows with a blank email are passed through unmerged.
 *
 * Run: select buildFinalMerged in the toolbar, click Run, then authorize.
 */

// ===== CONFIG: set source sheet name / range here =====
const SOURCE_SHEET = 'Responses';     // sheet holding the raw responses
const SOURCE_RANGE = 'A:F';           // Timestamp, Name, Email, JoinedBefore, Phone, PreferredPark (headers in first row)
const OUTPUT_SHEET = 'Final_Merged';  // created if missing, overwritten if present
// ======================================================

const FIELDS = ['Timestamp', 'Name', 'Email', 'JoinedBefore', 'Phone', 'PreferredPark'];
const TS = 0, EMAIL = 2, PHONE = 4;   // column indexes within FIELDS

function buildFinalMerged() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const src = ss.getSheetByName(SOURCE_SHEET);
  if (!src) throw new Error('Source sheet not found: ' + SOURCE_SHEET);

  const rng = src.getRange(SOURCE_RANGE);
  const values = rng.getValues();
  const firstRow = rng.getRow();

  // 1) Build records, skipping the header and fully blank rows.
  const records = [];
  for (let i = 1; i < values.length; i++) {
    const vals = values[i].slice(0, FIELDS.length);
    if (vals.every(isBlank)) continue;
    records.push({ row: firstRow + i, vals: vals, time: parseTime(vals[TS]) });
  }

  // 2) Group by normalized email (blank email = its own group).
  const groups = new Map();
  records.forEach(r => {
    const email = String(r.vals[EMAIL]).trim().toLowerCase();
    const key = email || ('__row' + r.row);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(r);
  });

  // 3) Merge each group.
  const output = [];
  groups.forEach(group => {
    // Newest first; on a timestamp tie, the lower sheet row (higher row number) first.
    group.sort((a, b) => {
      const ta = a.time === null ? -Infinity : a.time;
      const tb = b.time === null ? -Infinity : b.time;
      return tb !== ta ? tb - ta : b.row - a.row;
    });

    const keeper = group[0];
    const merged = keeper.vals.slice();
    merged[TS] = keeper.time === null ? keeper.vals[TS] : new Date(keeper.time);

    // Fill blanks on the keeper from the next-newest rows.
    for (let f = 1; f < FIELDS.length; f++) {
      if (isBlank(merged[f])) {
        const donor = group.find(r => !isBlank(r.vals[f]));
        if (donor) merged[f] = donor.vals[f];
      }
    }

    // Conflicts: more than one distinct non-blank (normalized) value in a field.
    const conflicts = [];
    for (let f = 1; f < FIELDS.length; f++) {
      if (f === EMAIL) continue; // email is the grouping key
      const distinct = new Set(
        group.filter(r => !isBlank(r.vals[f])).map(r => norm(FIELDS[f], r.vals[f]))
      );
      if (distinct.size > 1) conflicts.push(FIELDS[f]);
    }
    if (group.some(r => r.time === null)) conflicts.push('Timestamp (unparsed)');

    output.push({ row: keeper.row, data: merged.concat(conflicts.join(', ')) });
  });

  // 4) Keep the original sheet order (by keeper row).
  output.sort((a, b) => a.row - b.row);
  const rows = output.map(o => o.data);

  // 5) Write to the output sheet.
  const out = ss.getSheetByName(OUTPUT_SHEET) || ss.insertSheet(OUTPUT_SHEET);
  out.clearContents();
  const header = FIELDS.concat('Conflicts');
  out.getRange(1, 1, 1, header.length).setValues([header]).setFontWeight('bold');

  if (rows.length) {
    out.getRange(2, PHONE + 1, rows.length, 1).setNumberFormat('@');            // phone as plain text
    out.getRange(2, 1, rows.length, header.length).setValues(rows);
    out.getRange(2, TS + 1, rows.length, 1).setNumberFormat('m/d/yyyy hh:mm');  // timestamp format
  }
  out.setFrozenRows(1);

  ss.toast(records.length + ' rows read, ' + rows.length + ' rows written to ' + OUTPUT_SHEET, 'Done', 5);
}

/** True if a cell is empty or whitespace. */
function isBlank(v) {
  return v === null || v === '' || String(v).trim() === '';
}

/** Returns epoch ms, or null if the value isn't a usable date. */
function parseTime(v) {
  if (v instanceof Date) return isNaN(v.getTime()) ? null : v.getTime();
  if (isBlank(v)) return null;
  const d = new Date(String(v).trim()); // handles "4/3/2021 09:12", "03-Mar-2021", etc.
  return isNaN(d.getTime()) ? null : d.getTime();
}

/**
 * Normalizes values for conflict comparison only (merged output keeps the original text),
 * so "y" vs "yes", "(555)1234" vs "555-1234", and "West-side" vs "West Side" don't count as conflicts.
 */
function norm(field, v) {
  let s = String(v).trim().toLowerCase();
  if (field === 'JoinedBefore') {
    if (/^y(es)?$/.test(s)) return 'yes';
    if (/^no?$/.test(s)) return 'no';
  }
  if (field === 'Phone') {
    s = s.replace(/\D/g, '');
    return (s.length === 11 && s[0] === '1') ? s.slice(1) : s;
  }
  return s.replace(/[^a-z0-9]/g, '');
}
