}

/** Returns epoch ms, or null if the value isn't a usable date. */
function parseTime(v) {
  if (v instanceof Date) return isNaN(v.getTime()) ? null : v.getTime();
  if (isBlank(v)) return null;
  const d = new Date(String(v).trim()); // text dates like "4/3/2021 09:12"; unparseable text -> null
  return isNaN(d.getTime()) ? null : d.getTime();
}

/** Digits only, with a leading US country code 1 removed from 11-digit numbers. */
function phoneDigits(v) {
  const d = String(v).replace(/\D/g, '');
