}

/** True if any two phones differ, other than one being the tail of the other (7 vs 10 digits). */
function phonesConflict(list) {
  for (let i = 0; i < list.length; i++) {
    for (let j = i + 1; j < list.length; j++) {
      const a = list[i], b = list[j];
      if (!a.endsWith(b) && !b.endsWith(a)) return true;
    }
  }
  return false;
}

/**
 * Normalizes values for conflict comparison only (output keeps the original text),
 * so "y" vs "yes" and "West-side" vs "West Side" don't count as conflicts.
