  PARKMAP_SHEET: 'ParkMap',      // Col A = variant (e.g. "W. Side" or "wside"), Col B = canonical name

  DUP_WINDOW_MINUTES: 10,        // EDIT: same-name submissions within this many minutes = DUP-name-time

  DATE_ORDER: 'MDY',             // EDIT: 'MDY' (3/4/21 = Mar 4) or 'DMY' (3/4/21 = 3 Apr)
  TIMESTAMP_FORMAT: 'yyyy-mm-dd hh:mm',   // EDIT: display format for Timestamp_Clean

  // Phone rules
  PHONE_LENGTH: 10,              // EDIT: required digit count after cleanup
  PHONE_COUNTRY_CODE: '1',       // EDIT: stripped when number = country code + PHONE_LENGTH digits
  DEFAULT_AREA_CODE: '',         // EDIT: e.g. '212' to prepend to 7-digit numbers. Leave '' unless you are
                                 // CERTAIN every short number is local; otherwise they go to REVIEW.

  // Yes/No rules (compared lowercase, trimmed)
  YES_VALUES: ['y', 'yes'],      // EDIT: add variants like 'yep', 'true'
  NO_VALUES: ['n', 'no'],        // EDIT: add variants like 'nope', 'false'

  // EDIT: also send rows to REVIEW when email is blank AND the same name appears on another row
  REVIEW_NAME_MATCH_WITHOUT_EMAIL: true
};
// ===============================================================

const HEADERS = [
  'Timestamp', 'Name', 'Email', 'JoinedBefore', 'Phone', 'PreferredPark',     // A:F (raw copy)
  'JoinedBefore_Clean', 'Phone_Clean', 'Timestamp_Clean', 'Park_Clean',       // G:J
  'EmailKey', 'NameKey', 'DupEmail', 'DupNameTime', 'Superseded', 'Status'    // K:P
];

const FINAL_HEADERS = [
  'Timestamp_Clean', 'Name', 'Email', 'JoinedBefore_Clean', 'Phone_Clean', 'Park_Clean'
];

const MONTHS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('Survey Cleanup')
    .addItem('Run cleaning', 'cleanSurvey')
    .addToUi();
}

function cleanSurvey() {
  const ss = SpreadsheetApp.getActive();
  const raw = ss.getSheetByName(CONFIG.RAW_SHEET);
  if (!raw) throw new Error('Sheet "' + CONFIG.RAW_SHEET + '" not found.');

  // --- Read Raw (skip header row, drop fully blank rows) ---
  const lastRow = raw.getLastRow();
  const data = lastRow > 1 ? raw.getRange(2, 1, lastRow - 1, 6).getValues() : [];
  const rows = data.filter(r => r.some(c => String(c).trim() !== ''));

  const parkMap = loadParkMap_(ss);

  // --- Per-row normalization ---
  const recs = rows.map(r => ({
    raw: r,
    yn: normalizeYesNo_(r[3]),
    phone: normalizePhone_(r[4]),
    ts: parseTimestamp_(r[0]),
    park: mapPark_(r[5], parkMap),
    nameClean: String(r[1]).trim().replace(/\s+/g, ' '),
    emailKey: String(r[2]).trim().toLowerCase(),
    nameKey: String(r[1]).trim().replace(/\s+/g, ' ').toLowerCase()
  }));

  // --- Group by email and name ---
  const emailCount = {};
  const emailLatest = {};
  const byName = {};
  recs.forEach((r, i) => {
    if (r.emailKey) {
      emailCount[r.emailKey] = (emailCount[r.emailKey] || 0) + 1;
      if (r.ts && (!emailLatest[r.emailKey] || r.ts.getTime() > emailLatest[r.emailKey])) {
        emailLatest[r.emailKey] = r.ts.getTime();
      }
    }
    if (r.nameKey) {
      if (!byName[r.nameKey]) byName[r.nameKey] = [];
      byName[r.nameKey].push(i);
    }
  });

  // --- Flags and status ---
  const windowMs = CONFIG.DUP_WINDOW_MINUTES * 60 * 1000;
  recs.forEach((r, i) => {
    r.dupEmail = (r.emailKey && emailCount[r.emailKey] > 1) ? 'DUP-email' : '';

    r.dupNameTime = '';
    if (r.nameKey && r.ts) {
      for (const j of byName[r.nameKey]) {
        if (j !== i && recs[j].ts && Math.abs(recs[j].ts.getTime() - r.ts.getTime()) <= windowMs) {
          r.dupNameTime = 'DUP-name-time';
          break;
        }
      }
    }

    // Keep latest per email. Exact timestamp ties are NOT marked (both stay; resolve manually).
    r.superseded = (r.emailKey && r.ts && emailLatest[r.emailKey] &&
                    r.ts.getTime() < emailLatest[r.emailKey]) ? 'SUPERSEDED' : '';

    const nameMatchNoEmail = CONFIG.REVIEW_NAME_MATCH_WITHOUT_EMAIL &&
      !r.emailKey && r.nameKey && byName[r.nameKey].length > 1;

    r.status = (r.yn === 'REVIEW' || r.phone === 'REVIEW' || !r.ts || r.park === 'REVIEW' ||
                r.dupEmail || r.dupNameTime || nameMatchNoEmail) ? 'REVIEW' : 'OK';
  });

  // --- Clean sheet (all rows, raw copy + helpers) ---
  const cleanOut = recs.map(r => [
    safeText_(r.raw[0]), safeText_(r.raw[1]), safeText_(r.raw[2]),
    safeText_(r.raw[3]), safeText_(r.raw[4]), safeText_(r.raw[5]),
    r.yn, r.phone, r.ts || 'REVIEW', r.park,
    safeText_(r.emailKey), safeText_(r.nameKey),
    r.dupEmail, r.dupNameTime, r.superseded, r.status
  ]);
  rebuildSheet_(ss, CONFIG.CLEAN_SHEET, HEADERS, cleanOut,
                { 8: '@', 9: CONFIG.TIMESTAMP_FORMAT });            // H = Phone_Clean, I = Timestamp_Clean

  // --- Final sheet (cleaned columns only; Status = OK and not superseded) ---
  // Order: Timestamp_Clean, Name (cleaned), Email (original), JoinedBefore_Clean, Phone_Clean, Park_Clean
  const finalRecs = recs.filter(r => r.status === 'OK' && r.superseded === '');
  const finalOut = finalRecs.map(r => [
    r.ts,                    // Timestamp_Clean (always a valid Date for OK rows)
    safeText_(r.nameClean),  // Name, whitespace-trimmed/collapsed
    safeText_(r.raw[2]),     // Email exactly as entered in Raw
    r.yn,                    // JoinedBefore_Clean
    r.phone,                 // Phone_Clean
    r.park                   // Park_Clean
  ]);
  rebuildSheet_(ss, CONFIG.FINAL_SHEET, FINAL_HEADERS, finalOut,
                { 1: CONFIG.TIMESTAMP_FORMAT, 5: '@' });            // A = Timestamp_Clean, E = Phone_Clean

  // --- Summary sheet ---
  const nTotal = recs.length;
  const nOk = recs.filter(r => r.status === 'OK').length;
  const nReview = nTotal - nOk;
  const nSup = recs.filter(r => r.superseded).length;
  writeSummary_(ss, recs, finalRecs, { nTotal, nOk, nReview, nSup });

  ss.toast(`${nTotal} rows: ${nOk} OK, ${nReview} REVIEW, ${nSup} SUPERSEDED, ${finalRecs.length} in Final.`,
           'Survey Cleanup', 8);
}

// ===================== OUTPUT HELPERS =====================

// Clears (or creates) a sheet, writes headers + rows. formats = { columnNumber: numberFormat }.
function rebuildSheet_(ss, name, headers, rows, formats) {
  const sh = ss.getSheetByName(name) || ss.insertSheet(name);
  sh.clear();
  sh.getRange(1, 1, 1, headers.length).setValues([headers]).setFontWeight('bold');
  if (rows.length) {
    Object.keys(formats || {}).forEach(col => {
      sh.getRange(2, Number(col), rows.length, 1).setNumberFormat(formats[col]);  // set before writing
    });
    sh.getRange(2, 1, rows.length, headers.length).setValues(rows);
  }
  sh.setFrozenRows(1);
  return sh;
}

function writeSummary_(ss, recs, finalRecs, counts) {
  const sh = ss.getSheetByName(CONFIG.SUMMARY_SHEET) || ss.insertSheet(CONFIG.SUMMARY_SHEET);
  sh.clear();

  // Block 1: overall counts (A1:B7)
  const overall = [
    ['Metric', 'Count'],
    ['Total processed', counts.nTotal],
    ['OK', counts.nOk],
    ['REVIEW', counts.nReview],
    ['SUPERSEDED', counts.nSup],
    ['Rows in Final', finalRecs.length],
    ['Last run', new Date()]
  ];
  sh.getRange(1, 1, overall.length, 2).setValues(overall);
  sh.getRange(1, 1, 1, 2).setFontWeight('bold');
  sh.getRange(overall.length, 2).setNumberFormat('yyyy-mm-dd hh:mm');

  // Block 2: counts per Park_Clean, all rows vs. Final rows (starts two rows below block 1)
  const allCounts = {};
  const finalCounts = {};
  recs.forEach(r => { allCounts[r.park] = (allCounts[r.park] || 0) + 1; });
  finalRecs.forEach(r => { finalCounts[r.park] = (finalCounts[r.park] || 0) + 1; });

  const parks = Object.keys(allCounts).sort((a, b) => {
    if (a === 'REVIEW') return 1;                                   // unmapped bucket goes last
    if (b === 'REVIEW') return -1;
    return allCounts[b] - allCounts[a] || a.localeCompare(b);       // then by count desc, name asc
  });

  const parkRows = [['Park_Clean', 'All rows', 'Final rows']]
    .concat(parks.map(p => [safeText_(p), allCounts[p], finalCounts[p] || 0]));
  const startRow = overall.length + 2;
  sh.getRange(startRow, 1, parkRows.length, 3).setValues(parkRows);
  sh.getRange(startRow, 1, 1, 3).setFontWeight('bold');

  sh.setFrozenRows(1);
  sh.autoResizeColumns(1, 3);
}

// ===================== NORMALIZATION HELPERS =====================

function normalizeYesNo_(v) {
  const s = String(v).trim().toLowerCase();
  if (!s) return 'REVIEW';
  if (CONFIG.YES_VALUES.includes(s)) return 'Yes';
  if (CONFIG.NO_VALUES.includes(s)) return 'No';
  return 'REVIEW';
}

function normalizePhone_(v) {
  let d = String(v).replace(/\D/g, '');
  if (!d) return 'REVIEW';
  const cc = CONFIG.PHONE_COUNTRY_CODE;
  if (cc && d.length === CONFIG.PHONE_LENGTH + cc.length && d.startsWith(cc)) {
    d = d.slice(cc.length);
  }
  const ac = CONFIG.DEFAULT_AREA_CODE;
  if (ac && d.length + ac.length === CONFIG.PHONE_LENGTH) d = ac + d;
  return d.length === CONFIG.PHONE_LENGTH ? d : 'REVIEW';
}

function parkKey_(v) {
  return String(v).toLowerCase().replace(/[^a-z]/g, '');
}

function loadParkMap_(ss) {
  const sh = ss.getSheetByName(CONFIG.PARKMAP_SHEET);
  if (!sh) throw new Error('Sheet "' + CONFIG.PARKMAP_SHEET + '" not found (Col A = variant, Col B = canonical).');
  const map = {};
  sh.getDataRange().getValues().forEach((row, idx) => {
    if (idx === 0 && String(row[0]).trim().toLowerCase() === 'key') return;   // skip header row
    const variant = parkKey_(row[0]);
    const canonical = String(row[1] || '').trim();
    if (!variant || !canonical) return;
    map[variant] = canonical;
    const selfKey = parkKey_(canonical);                                       // canonical maps to itself
    if (selfKey && !map[selfKey]) map[selfKey] = canonical;
  });
  return map;
}

function mapPark_(v, map) {
  const key = parkKey_(v);
  if (!key) return 'REVIEW';
  return map[key] || 'REVIEW';   // Unmapped -> REVIEW; add the variant to ParkMap and re-run
}

// Returns a valid Date or null. Handles real date cells, "4/3/2021 09:12", "04-03-21",
// "2021-04-03 14:01", "03-Mar-2021", "3 Mar 2021", "Mar 3, 2021", with optional time and am/pm.
function parseTimestamp_(v) {
  if (v instanceof Date) return isNaN(v.getTime()) ? null : v;
  const s = String(v).trim().toLowerCase();
  if (!s) return null;

  let y, m, d, rest;
  let mt;
  if ((mt = s.match(/^(\d{4})[\/\-.](\d{1,2})[\/\-.](\d{1,2})(.*)$/))) {              // Y-M-D
    y = +mt[1]; m = +mt[2]; d = +mt[3]; rest = mt[4];
  } else if ((mt = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})(.*)$/))) {     // M/D/Y or D/M/Y
    const a = +mt[1], b = +mt[2];
    if (CONFIG.DATE_ORDER === 'DMY') { d = a; m = b; } else { m = a; d = b; }
    y = +mt[3]; rest = mt[4];
  } else if ((mt = s.match(/^(\d{1,2})[\s\-\/]+([a-z]{3,})\.?[\s\-\/,]+(\d{2,4})(.*)$/))) {  // 03-Mar-2021
    d = +mt[1]; m = monthIndex_(mt[2]); y = +mt[3]; rest = mt[4];
  } else if ((mt = s.match(/^([a-z]{3,})\.?\s+(\d{1,2}),?\s+(\d{2,4})(.*)$/))) {            // Mar 3, 2021
    m = monthIndex_(mt[1]); d = +mt[2]; y = +mt[3]; rest = mt[4];
  } else {
    return null;
  }
  if (!m) return null;
  if (y < 100) y += (y < 70 ? 2000 : 1900);

  let h = 0, mi = 0, sec = 0;
  const tm = (rest || '').match(/(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(am|pm)?/);
  if (tm) {
    h = +tm[1]; mi = +tm[2]; sec = tm[3] ? +tm[3] : 0;
    if (tm[4] === 'pm' && h < 12) h += 12;
    if (tm[4] === 'am' && h === 12) h = 0;
    if (h > 23 || mi > 59 || sec > 59) return null;
  } else if ((rest || '').trim()) {
    return null;                                    // unexpected trailing text -> REVIEW
  }

  const dt = new Date(y, m - 1, d, h, mi, sec);
  if (dt.getFullYear() !== y || dt.getMonth() !== m - 1 || dt.getDate() !== d) return null;  // e.g. 2/30
  return dt;
}

function monthIndex_(name) {
  const i = MONTHS.indexOf(String(name).slice(0, 3).toLowerCase());
  return i === -1 ? 0 : i + 1;
}

// Prevents text like "+1 555 1236" or "=..." from being interpreted as a formula when written back.
function safeText_(v) {
  if (typeof v !== 'string') return v;
  return /^[=+\-@]/.test(v) ? "'" + v : v;
}
```

Here's the script. Paste the whole thing into **Extensions > Apps Script**, save, and run each function separately from the editor's Run menu (or add a quick UI menu if you prefer — the optional block at the bottom does that).

**Permissions it will request:** "See, edit, create, and delete your spreadsheets." That's the standard Sheets scope; it doesn't touch Drive, Gmail, or anything else.

---

```javascript
// ── CONFIG ──────────────────────────────────────────────────────────────────
const RAW_SHEET   = "Sheet1";   // name of your raw/clean data sheet
const PARK_COL    = 6;          // column F = PreferredPark (1-indexed)
const CLEAN_COL   = 10;         // column J = Clean park output (1-indexed)
const HEADER_ROW  = 1;          // row 1 is headers, data starts row 2
const PARKMAP_SHEET = "ParkMap";
// ────────────────────────────────────────────────────────────────────────────

/** Step 1 — Build ParkMap with distinct keys and counts. */
function buildParkMap() {
  const ss      = SpreadsheetApp.getActiveSpreadsheet();
  const rawSh   = ss.getSheetByName(RAW_SHEET);
  const lastRow = rawSh.getLastRow();

  // Pull raw park values (column F, skipping header)
  const parkValues = rawSh
    .getRange(HEADER_ROW + 1, PARK_COL, lastRow - HEADER_ROW, 1)
    .getValues()
    .flat();

  // Build key → count map
  const counts = {};
  for (const val of parkValues) {
    const key = normalize(val);
    if (key === "") continue;
    counts[key] = (counts[key] || 0) + 1;
  }

  // Write or clear the ParkMap sheet
  let pmSh = ss.getSheetByName(PARKMAP_SHEET);
  if (!pmSh) {
    pmSh = ss.insertSheet(PARKMAP_SHEET);
  } else {
    pmSh.clearContents();
  }

  const rows = [["key", "canonical", "count"]];
  for (const [key, count] of Object.entries(counts).sort()) {
    rows.push([key, "", count]);   // leave canonical blank for you to fill
  }
  pmSh.getRange(1, 1, rows.length, 3).setValues(rows);

  SpreadsheetApp.getUi().alert(
    `ParkMap built: ${rows.length - 1} distinct keys. Fill column B, then run applyParkMap.`
  );
}

/** Step 2 — Read filled ParkMap and write canonical names into Clean!J. */
function applyParkMap() {
  const ss    = SpreadsheetApp.getActiveSpreadsheet();
  const rawSh = ss.getSheetByName(RAW_SHEET);
  const pmSh  = ss.getSheetByName(PARKMAP_SHEET);

  if (!pmSh) {
    SpreadsheetApp.getUi().alert("Run buildParkMap first.");
    return;
  }

  // Load ParkMap into a lookup object (skip header row)
  const pmData = pmSh.getDataRange().getValues();
  const lookup = {};
  for (let i = 1; i < pmData.length; i++) {
    const key       = String(pmData[i][0]).trim();
    const canonical = String(pmData[i][1]).trim();
    if (key !== "" && canonical !== "") lookup[key] = canonical;
  }

  // Read raw park column, write cleaned values to CLEAN_COL
  const lastRow   = rawSh.getLastRow();
  const dataRows  = lastRow - HEADER_ROW;
  const parkRange = rawSh.getRange(HEADER_ROW + 1, PARK_COL, dataRows, 1);
  const parkVals  = parkRange.getValues();

  const output = parkVals.map(([val]) => {
    const key = normalize(val);
    if (key === "") return ["REVIEW"];
    return [lookup[key] ?? "REVIEW"];
  });

  rawSh.getRange(HEADER_ROW + 1, CLEAN_COL, dataRows, 1).setValues(output);

  const reviewed = output.filter(r => r[0] === "REVIEW").length;
  SpreadsheetApp.getUi().alert(
    `Done. ${output.length - reviewed} mapped, ${reviewed} marked REVIEW.`
  );
}

/** Normalize a raw park string to a lookup key. */
function normalize(val) {
  return String(val).toLowerCase().replace(/[^a-z]/g, "").trim();
}

// ── OPTIONAL: adds a menu so you can run from the sheet, not just the editor ─
function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("🧹 Data Tools")
    .addItem("1. Build ParkMap",  "buildParkMap")
    .addItem("2. Apply ParkMap",  "applyParkMap")
    .addToUi();
}
