  const lastRow  = rawSh.getLastRow();
  const dataRows = lastRow - HEADER_ROW;
  const parkVals = rawSh
    .getRange(HEADER_ROW + 1, PARK_COL, dataRows, 1)
    .getValues();

  // Map values and collect unmapped info in one pass
  const output   = [];
  const unmapped = {};  // key → { count, rows[] }

  parkVals.forEach(([val], i) => {
    const key      = normalize(val);
    const sheetRow = i + HEADER_ROW + 1;  // 1-indexed sheet row number

    if (key === "") {
      output.push(["REVIEW"]);
      return;
    }

    if (lookup[key]) {
      output.push([lookup[key]]);
    } else {
      output.push(["REVIEW"]);
      if (!unmapped[key]) unmapped[key] = { count: 0, rows: [] };
      unmapped[key].count++;
      if (unmapped[key].rows.length < MAX_EXAMPLES) {
        unmapped[key].rows.push(sheetRow);
      }
    }
  });

  // Write cleaned values to CLEAN_COL
  rawSh.getRange(HEADER_ROW + 1, CLEAN_COL, dataRows, 1).setValues(output);

  // Write Unmapped sheet
  let umSh = ss.getSheetByName(UNMAPPED_SHEET);
  if (!umSh) {
    umSh = ss.insertSheet(UNMAPPED_SHEET);
  } else {
    umSh.clearContents();
  }

  const umRows = [["key", "count", "example_rows"]];
  for (const [key, info] of Object.entries(unmapped).sort((a, b) => b[1].count - a[1].count)) {
    umRows.push([key, info.count, info.rows.join(", ")]);
  }

  if (umRows.length > 1) {
    umSh.getRange(1, 1, umRows.length, 3).setValues(umRows);
  } else {
    umSh.getRange(1, 1, 1, 3).setValues([["key", "count", "example_rows"]]);
    umSh.getRange(2, 1).setValue("All keys mapped — nothing to review.");
  }
}

function normalize(val) {
  return String(val).toLowerCase().replace(/[^a-z]/g, "").trim();
}

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("🧹 Data Tools")
    .addItem("1. Build ParkMap",  "buildParkMap")
    .addItem("2. Apply ParkMap",  "applyParkMap")
