```javascript
function cleanVolunteerData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getActiveSheet();
  const data = sheet.getDataRange().getValues();

  const DEFAULT_AREA_CODE_CELL = "Z1";
  const defaultAreaCode = sheet.getRange(DEFAULT_AREA_CODE_CELL).getValue().toString().replace(/\D/g, "");

  // Column indices (0-based). Adjust if your layout differs.
  const COL = {
    timestamp:     0,  // A - raw timestamp
    name:          1,  // B
    email:         2,  // C
    joinedBefore:  6,  // G - cleaned Yes/No
    phone:         7,  // H - cleaned phone
    timestamp_c:   8,  // I - cleaned timestamp
    park:          9,  // J - cleaned park
    reviewFlag:   15,  // P - review flag (0-based = col 16)
  };

  // Output columns (0-based). These will be written or created.
  const OUT = {
    cleanedJoined:    16,  // Q
    cleanedPhone:     17,  // R
    cleanedTimestamp: 18,  // S
    cleanedPark:      19,  // T
    superseded:       20,  // U
    conflicts:        21,  // V
  };

  const HEADER_ROW = 0;
  const headers = data[HEADER_ROW];

  // Write output headers if the row is the header row.
  const outputHeaders = ["CleanedJoined", "CleanedPhone", "CleanedTimestamp", "CleanedPark", "Superseded", "Conflicts"];
  outputHeaders.forEach((h, i) => {
    sheet.getRange(1, OUT.cleanedJoined + i + 1).setValue(h);
  });

  // ── Helpers ──────────────────────────────────────────────────────────────

  function normalizePhone(raw) {
    if (!raw) return "";
    const digits = raw.toString().replace(/\D/g, "");
    if (digits.length === 10) return digits;
    if (digits.length === 11 && digits[0] === "1") return digits.slice(1);
    if (digits.length === 7 && defaultAreaCode.length === 3) return defaultAreaCode + digits;
    return "";
  }

  function normalizeEmail(raw) {
    return raw ? raw.toString().trim().toLowerCase() : "";
  }

  function normalizeName(raw) {
    return raw ? raw.toString().trim().toLowerCase().replace(/\s+/g, " ") : "";
  }

  function parseTimestamp(val) {
    if (!val) return null;
    if (val instanceof Date) return val;
    const d = new Date(val);
    return isNaN(d.getTime()) ? null : d;
  }

  function withinMinutes(ts1, ts2, minutes) {
    if (!ts1 || !ts2) return false;
    return Math.abs(ts1.getTime() - ts2.getTime()) <= minutes * 60 * 1000;
  }

  function completenessScore(row) {
    const fields = [
      row[COL.joinedBefore],
      normalizePhone(row[COL.phone]),
      row[COL.park],
      normalizeEmail(row[COL.email]),
    ];
    return fields.filter(f => f && f.toString().trim() !== "" && f.toString().trim() !== "REVIEW").length;
  }

  function getConflicts(rows) {
    const fieldNames = ["JoinedBefore", "Phone", "PreferredPark", "Email"];
    const getters = [
      r => r[COL.joinedBefore],
      r => normalizePhone(r[COL.phone]),
      r => r[COL.park],
      r => normalizeEmail(r[COL.email]),
    ];
    const conflicting = [];
    fieldNames.forEach((name, i) => {
      const values = rows.map(r => (getters[i](r) || "").toString().trim().toLowerCase());
      const unique = [...new Set(values.filter(v => v !== "" && v !== "review"))];
      if (unique.length > 1) conflicting.push(name);
    });
    return conflicting.join(", ");
  }

  // ── Build row objects (skip header) ──────────────────────────────────────

  const rows = data.slice(1).map((row, i) => ({
    rowIndex: i + 1,          // 0-based index into data array
    sheetRow: i + 2,          // 1-based sheet row number
    data: row,
    email: normalizeEmail(row[COL.email]),
    name: normalizeName(row[COL.name]),
    timestamp: parseTimestamp(row[COL.timestamp_c]) || parseTimestamp(row[COL.timestamp]),
    score: 0,
    groupId: null,
  }));

  rows.forEach(r => { r.score = completenessScore(r.data); });

  // ── Group rows by email or name+timestamp proximity ───────────────────────

  let nextGroupId = 0;

  function mergeGroups(a, b) {
    if (a.groupId === null && b.groupId === null) {
      a.groupId = b.groupId = nextGroupId++;
    } else if (a.groupId === null) {
      a.groupId = b.groupId;
    } else if (b.groupId === null) {
      b.groupId = a.groupId;
    } else if (a.groupId !== b.groupId) {
      const old = b.groupId;
      rows.forEach(r => { if (r.groupId === old) r.groupId = a.groupId; });
    }
  }

  for (let i = 0; i < rows.length; i++) {
    for (let j = i + 1; j < rows.length; j++) {
      const a = rows[i], b = rows[j];
      const sameEmail = a.email && b.email && a.email === b.email;
      const sameName = a.name && b.name && a.name === b.name;
      const closeTime = withinMinutes(a.timestamp, b.timestamp, 10);
      if (sameEmail || (sameName && closeTime)) mergeGroups(a, b);
    }
  }

  // ── Decide winner per group, write output ────────────────────────────────

  const groups = {};
  rows.forEach(r => {
    if (r.groupId !== null) {
      if (!groups[r.groupId]) groups[r.groupId] = [];
      groups[r.groupId].push(r);
    }
  });

  // Prepare a batch of output values indexed by sheetRow.
  const output = {};
  rows.forEach(r => {
    output[r.sheetRow] = {
      cleanedJoined:    r.data[COL.joinedBefore] || "",
      cleanedPhone:     normalizePhone(r.data[COL.phone]),
      cleanedTimestamp: r.data[COL.timestamp_c] || "",
      cleanedPark:      r.data[COL.park] || "",
      superseded:       "",
      conflicts:        "",
    };
  });

  Object.values(groups).forEach(group => {
    group.sort((a, b) => b.score - a.score);
    const winner = group[0];
    const conflicts = getConflicts(group.map(r => r.data));

    group.forEach(r => {
      output[r.sheetRow].conflicts = conflicts;
      if (r.sheetRow !== winner.sheetRow) {
        output[r.sheetRow].superseded = "SUPERSEDED";
        output[r.sheetRow].cleanedJoined    = winner.data[COL.joinedBefore] || "";
        output[r.sheetRow].cleanedPhone     = normalizePhone(winner.data[COL.phone]);
        output[r.sheetRow].cleanedTimestamp = winner.data[COL.timestamp_c] || "";
        output[r.sheetRow].cleanedPark      = winner.data[COL.park] || "";
      }
    });
  });

  // ── Write output in one batch ─────────────────────────────────────────────

  rows.forEach(r => {
    const o = output[r.sheetRow];
    sheet.getRange(r.sheetRow, OUT.cleanedJoined + 1, 1, 6).setValues([[
      o.cleanedJoined,
      o.cleanedPhone,
      o.cleanedTimestamp,
      o.cleanedPark,
      o.superseded,
      o.conflicts,
    ]]);
  });

  SpreadsheetApp.getUi().alert("Done. Check columns Q–V for cleaned values, Superseded, and Conflicts.");
}
```

