  const headerRange = sheet.getRange(1, OUT.cleanedJoined + 1, 1, 6);
  if (headerRange.getValues()[0].every(cell => cell.toString().trim() === "")) {
    headerRange.setValues([["CleanedJoined","CleanedPhone","CleanedTimestamp","CleanedPark","Superseded","Conflicts"]]);
  }

  // ── Resolve groups: non-review first, then score desc, then timestamp desc ─

  const groups = {};
  rows.forEach(r => {
    if (r.groupId !== null) {
      (groups[r.groupId] = groups[r.groupId] || []).push(r);
    }
  });

  const winnerFields = {};
  Object.values(groups).forEach(group => {
    group.sort((a, b) =>
      a.underReview - b.underReview ||
      b.score - a.score ||
      (b.timestamp && a.timestamp ? b.timestamp.getTime() - a.timestamp.getTime() : 0)
    );
    const w = group[0].data;
    winnerFields[group[0].groupId] = {
      joined:    w[COL.joinedBefore],
      phone:     normalizePhone(w[COL.phone]),
      timestamp: w[COL.timestamp_c],
      park:      w[COL.park],
      email:     normalizeEmail(w[COL.email]),  // carried for copying, not output as own column
    };
  });

  // ── Build and write output (6 columns: Q–V) ───────────────────────────────

  const outputValues = rows.map(r => {
    const out = {
      joined:    r.data[COL.joinedBefore],
      phone:     normalizePhone(r.data[COL.phone]),
      timestamp: r.data[COL.timestamp_c],
      park:      r.data[COL.park],
      superseded:"",
      conflicts: "",
    };

    if (r.groupId !== null) {
      const group  = groups[r.groupId];
      const winner = group[0];
      const wf     = winnerFields[r.groupId];

      out.conflicts = getConflicts(group.map(g => g.data));

      if (r.sheetRow !== winner.sheetRow) {
        out.superseded = "SUPERSEDED";
        if (isUsable(wf.joined)    && !isUsable(out.joined))    out.joined    = wf.joined;
        if (isUsable(wf.phone)     && !isUsable(out.phone))     out.phone     = wf.phone;
        if (isUsable(wf.timestamp) && !isUsable(out.timestamp)) out.timestamp = wf.timestamp;
        if (isUsable(wf.park)      && !isUsable(out.park))      out.park      = wf.park;
        // Email copied into raw column C on superseded rows, not to a new output column
        if (isUsable(wf.email) && !isUsable(r.data[COL.email])) {
          sheet.getRange(r.sheetRow, COL.email + 1).setValue(wf.email);
        }
      }
    }

    return [out.joined, out.phone, out.timestamp, out.park, out.superseded, out.conflicts];
  });

  sheet.getRange(2, OUT.cleanedJoined + 1, outputValues.length, 6).setValues(outputValues);

  SpreadsheetApp.getUi().alert("Done. Columns Q-V updated on sheet 'Responses'.");
}
```

---

The only substantive changes are these. `CleanedEmail` is gone from `OUT` entirely, and the output array and `setValues` call are back to 6 columns. The email copy now writes directly to the raw `COL.email` column (C) on superseded rows via a single-cell `setValue` — only when the winner has a usable email and the target cell is empty, same guard as before. The header check is unchanged in logic (it was already `every`), but the range is correctly back to 6 columns so it won't accidentally read into W.

One thing to be aware of: writing the winner's email back into column C means it modifies raw data. If you'd rather keep C untouched, the alternative is to include email in the cleaned block but not expose it as a visible output column — just let it live in a hidden column. Let me know if you'd prefer that approach.

## Dynamic Range Versions

The key shift is replacing `A2:A421` with `A2:A` (open-ended). Sheets evaluates only populated cells in COUNTIF/COUNTIFS with open ranges, so this is safe and won't drag in thousands of blank rows.

---

### Summary Panel — Dynamic Formulas

```
Total responses:      =COUNTA(Raw!A2:A)
Flagged REVIEW:       =COUNTIF(Raw!P2:P,"REVIEW")
Final rows:           =COUNTIFS(Raw!P2:P,"OK",Raw!O2:O,"")
```

Safer unique volunteers (excludes blank emails):
```
=SUMPRODUCT(
  (Raw!C2:C<>"")*
  (Raw!P2:P="OK")*
  (Raw!O2:O="")/
  IF(COUNTIFS(Raw!C2:C,Raw!C2:C,Raw!P2:P,"OK",Raw!O2:O,"")=0,
     1,
     COUNTIFS(Raw!C2:C,Raw!C2:C,Raw!P2:P,"OK",Raw!O2:O,"")))
```
This counts unique emails among accepted, non-superseded rows only, and skips blanks cleanly.

Joined Before % (accepted rows only):
```
=COUNTIFS(Raw!G2:G,"Yes",Raw!P2:P,"OK",Raw!O2:O,"")
/COUNTIFS(Raw!P2:P,"OK",Raw!O2:O,"")
```

Park counts (put canonical name in D column, formula in E):
```
=COUNTIFS(Raw!J2:J,D2,Raw!P2:P,"OK",Raw!O2:O,"")
```

---

### Final Sheet — Header + A:F Only

In `Final!A1`, paste the header manually or use:
```
=Raw!A1:F1
```
This spills across A1:F1 automatically.

In `Final!A2`, paste:
```
=IFERROR(
  FILTER(Raw!A2:F,
         Raw!P2:P="OK",
         Raw!O2:O=""),
  "No accepted rows yet.")
```
Pulling `A2:F` (no column limit on F) gives you exactly the six original columns. FILTER stops at the last populated row, so it stays dynamic without dragging anything.

