 * G Yes/No | H Phone | I Timestamp | J Park | K Email key | L Name key
 * M DUP-email | N DUP-name-time | O SUPERSEDED | P REVIEW/OK
 */
var CFG = { RAW: 'Raw', MAP: 'ParkMap', WINDOW_MIN: 10, MIN_YEAR: 1990, MAX_YEAR: 2100 };
var MON = {jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,nov:11,dec:12};

function cleanSurvey() {
  var ss = SpreadsheetApp.getActive();
  var sh = ss.getSheetByName(CFG.RAW), mapSh = ss.getSheetByName(CFG.MAP);
  if (!sh) throw new Error('Sheet "' + CFG.RAW + '" not found.');
  if (!mapSh) throw new Error('Sheet "' + CFG.MAP + '" not found.');
  var last = sh.getLastRow();
  if (last < 2) return;
  var n = last - 1;
  var data = sh.getRange(2, 1, n, 6).getValues();

  // Park map: key = lowercased letters only. Canonical names also map to themselves.
  var park = {};
  var ml = mapSh.getLastRow();
  if (ml > 1) mapSh.getRange(2, 1, ml - 1, 2).getValues().forEach(function (r) {
    var canon = String(r[1]).trim();
    if (!canon) return;
    if (letters(r[0])) park[letters(r[0])] = canon;
    park[letters(canon)] = canon;
  });

  // Pass 1: clean each row. Fully empty rows are marked blank and skipped.
  var rows = data.map(function (r) {
    if (r.every(function (c) { return String(c).trim() === ''; })) return { blank: true };
    var t = parseTime(r[0]), pk = letters(r[5]);
    return {
      yn: yesNo(r[3]), ph: phone(r[4]), t: t, ts: t ? t.getTime() : null,
      pk: pk && park[pk] ? park[pk] : 'REVIEW',
      ek: String(r[2]).trim().toLowerCase(),
      nk: String(r[1]).toLowerCase().replace(/\s+/g, ' ').trim()
    };
  });

  // Counts for duplicate checks
  var eCount = {}, nCount = {};
  rows.forEach(function (a) {
    if (a.blank) return;
    if (a.ek) eCount[a.ek] = (eCount[a.ek] || 0) + 1;
    if (a.nk) nCount[a.nk] = (nCount[a.nk] || 0) + 1;
  });

  // Pass 2: duplicate flags, SUPERSEDED, and "answers differ" check (O(n^2), fine for hundreds of rows)
  var win = CFG.WINDOW_MIN * 60000;
  var sig = function (x) { return x.yn + '|' + x.ph + '|' + x.pk; };
  rows.forEach(function (a, i) {
    if (a.blank) return;
    a.dupE = a.ek && eCount[a.ek] > 1 ? 'DUP-email' : '';
    a.dupN = ''; a.sup = ''; a.diff = false;
    rows.forEach(function (b, j) {
      if (i === j || b.blank) return;
      var sameE = a.ek && a.ek === b.ek;
      var near = a.nk && a.nk === b.nk && a.ts !== null && b.ts !== null &&
                 Math.abs(a.ts - b.ts) <= win;
      if (near) a.dupN = 'DUP-name-time';
      if ((sameE || near) && sig(a) !== sig(b)) a.diff = true;
      // Keep newest per email; on an exact timestamp tie, keep the lower row
      if (sameE && a.ts !== null && b.ts !== null && (b.ts > a.ts || (b.ts === a.ts && j > i)))
        a.sup = 'SUPERSEDED';
    });
  });

  // Build output G:P
  var out = rows.map(function (a) {
    if (a.blank) return ['', '', '', '', '', '', '', '', '', ''];
    var review =
      [a.yn, a.ph, a.t ? '' : 'REVIEW', a.pk].indexOf('REVIEW') > -1 ||
      a.diff ||                                    // duplicate candidates whose answers differ
      (!a.ek && a.nk && nCount[a.nk] > 1);         // no email, but name matches another row
    return [a.yn, a.ph, a.t || 'REVIEW', a.pk, a.ek, a.nk,
            a.dupE, a.dupN, a.sup, review ? 'REVIEW' : 'OK'];
  });

  sh.getRange(1, 7, 1, 10).setValues([['YesNo', 'PhoneClean', 'TimestampClean', 'ParkClean',
    'EmailKey', 'NameKey', 'DupEmail', 'DupNameTime', 'Superseded', 'Status']]);
  sh.getRange(2, 7, n, 10).clearContent();
  sh.getRange(2, 8, n, 1).setNumberFormat('@');                    // phones as text
  sh.getRange(2, 9, n, 1).setNumberFormat('yyyy-mm-dd hh:mm');
  sh.getRange(2, 7, n, 10).setValues(out);
}

